-- Дело 9704 v2: финальная проверка предъявлений (варианты по стадиям, правки). Партии не сбрасываются.
begin;
update characters set reaction_rules = '[{"id": "R03", "on": "b4e6a60f-b233-543e-b3b1-ae0a1427b6a1", "requires": [], "text": "Сеитова раскладывает кальку на капоте служебного «уазика».\n— Два типа следов. Первый: мужская зимняя обувь, сорок третий размер. Протектор глубокий, на каблуке косой порез, около сантиметра. Следы под тонким слоем снега. Снег, по метеостанции, пошёл около часа ночи на воскресенье. Значит, следы ночные, до часу.\nВторой: женская обувь, тридцать седьмой. Эти под подмёрзшей коркой слякоти. Оставлены раньше, засветло, пока грязь была мягкая.\nИ борозды. Две, параллельные, со стороны водительской двери. Тело несли, ноги волочились. Чьи следы — не скажу. Размер скажу.", "grants": ["60950128-af31-513e-b8de-bb87b02332cc"]}, {"id": "R24", "on": "46e78eb0-d057-5e5d-8a00-81457f8f3d20", "requires": ["4f67be3f-f5f7-5ab5-bb69-611053df3042"], "text": "Сеитова не поднимает головы от стола.\n— Три тысячи. Тридцать купюр по сто. Сверила с ксерокопиями: серия, номер. У двух купюр надрыв на краю, на копии он тоже виден. Все тридцать есть в копиях выкупа. Совпадение полное. Протокол сравнения подпишу сегодня. Как они попали к нему за подкладку — это не ко мне.", "grants": ["d91852b9-daca-5340-80c9-a13cffe680cc"]}, {"id": "R27", "on": "00b31a8e-e1ee-5474-a323-177b43b153d3", "requires": ["60950128-af31-513e-b8de-bb87b02332cc"], "text": "Сеитова снимает перчатки.\n— Сорок третий. Протектор тот же. Порез на каблуке косой, около сантиметра, края совпадают со слепком у гаража. Ботинки мыли, но в шве у подошвы грязь осталась, на экспертизу хватит. Подошву сравнила с калькой по шести точкам. Совпали все шесть.\nМужские следы у гаража дачи оставлены этими ботинками. Кто был в ботинках — вопрос не ко мне.", "grants": ["6fc41a46-a0eb-5890-9b26-3b19bcef490d"]}, {"id": "R28", "on": "2d1a03f4-be7f-5007-8fe1-71c12d498c29", "requires": ["4f67be3f-f5f7-5ab5-bb69-611053df3042"], "text": "Сеитова кладёт стопку протоколов рядом с листами ксерокопий.\n— Доллары из мешка с рисом. Пересчитала при понятых, номера переписала, сверила с копиями Ахметова лист за листом. Каждая купюра из тайника есть в копиях выкупа. Лишних нет. Чужих нет. Банковские резинки описаны. Рис описан отдельно.", "grants": ["107fcb2c-e909-5f81-bba4-d218265227c5"]}, {"id": "R30", "on": "4f67be3f-f5f7-5ab5-bb69-611053df3042", "requires": ["5cdb3307-fe10-53c5-a365-6998256b7d7a", "f725c4c5-f254-5c01-b718-3531a957102a"], "text": "Вы кладёте рядом с конвертом «на похороны» показания Шнайдер: тот, кто принёс конверт, в субботу вечером был у дома Шмидтов.\nСеитова раскладывает купюры рядом с листами ксерокопий.\n— Конверт от матери покойного. Пять купюр по сто, новые, «с маленькой головой». Сверила номера. Все пять есть в копиях выкупа. Совпадение полное. Надпись карандашом «От Фархада — на похороны» внесла в протокол. Больше по конверту ничего.", "grants": ["26a10711-a53c-5105-9ed4-190697869496"]}, {"id": "R47", "on": "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44", "requires": [], "text": "Сеитова вскрывает корпус пейджера над лотком, сливает мутную воду. Плату оставляет сохнуть на батарее. Наутро ставит новую батарейку.\n— Включился. Последнее принятое сообщение в памяти: четверг, двадцать первое, семнадцать тридцать пять. Позже ничего. В воде аппарат не принимает. Что на него слали после — это у оператора, к Абишеву. Арык у ворот сфотографировала. Где лежал — в протоколе.", "grants": ["7ada2011-2720-5b69-8a9c-9291fdad70e9"]}, {"id": "R50", "on": "60950128-af31-513e-b8de-bb87b02332cc", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "Сеитова раскладывает кальки.\n— Обувь. Нуртазин: форменные ботинки, сорок третий, протектор другого рисунка. Ахметов: сорок третий. Изъяла у него всё, что есть. Импортные туфли — подошва гладкая, кожаная. Зимние ботинки — протектор другой, пореза нет. Жумабаева: тридцать седьмой. Мужские следы у гаража ни одна из этих пар не оставила. Пары с порезом на каблуке среди того, что принесли, нет.", "grants": ["7a9bdd9a-4323-5342-a3bd-24301a6d6e88"]}, {"id": "R59", "on": "5cdb3307-fe10-53c5-a365-6998256b7d7a", "requires": ["4f67be3f-f5f7-5ab5-bb69-611053df3042", "27ae146a-a05c-5e7a-84a1-899c35e883e4"], "text": "Вы приносите Сеитовой конверт «на похороны» и напоминаете: пальцы того, кто его принёс, сняты с люка в подвале Шмидтов.\nСеитова кладёт пять купюр рядом с листами ксерокопий. Ведёт линейкой по строчкам.\n— Все пять есть в копиях выкупа. Серия, номер — совпадение полное. Протокол сравнения подпишу сегодня.", "grants": ["26a10711-a53c-5105-9ed4-190697869496"]}, {"id": "R60", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "Сеитова кладёт рядом две кальки.\n— Дактокарта Бекенова. Второй набор с крышки люка — его, по восьми признакам. Ахметова откатала тоже, он пришёл сам: с люком не совпадает. Кан смотрел кисти у обоих — свежих повреждений нет. Кровь у Бекенова — вторая группа, справка Кана. Абишев по ГАИ: водительского удостоверения и машины у Бекенова нет, говорит, что водить умеет. Свела всё в одну бумагу.", "grants": ["9281d556-d163-5537-a0e2-e4cd2e635ba5"]}, {"id": "R64", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"], "text": "Сеитова возвращается со стоянки Медеуского РОВД. На рукаве халата рыжая полоса глины.\n— Раз не угар, смотреть надо машину. Посмотрела. В колёсных арках жёлтая глина. Плотная, налипла слоем. Такая бывает на немощёных улицах частного сектора. В Горном Гиганте, например. На Кок-Тобе к даче асфальт и щебень, там такую не наберёшь.\nРуль: ни одного отпечатка. Ни чужого, ни хозяйского. Последним машину вёл человек в перчатках. Кто — не моя графа.", "grants": ["3772cdd6-1fe9-52d0-a268-3f82441220c7"]}, {"id": "R67", "on": "a9b47e33-f5b4-57b9-9e16-1e41c38e7834", "requires": [], "text": "Сеитова трёт сажу между пальцами, нюхает.\n— Свежая. Мотор работал часа три, не меньше, на холостых, при закрытых воротах. Бак, говорите, сухой? Сходится.\n(вытирает руку платком)\nТолько копоть не скажет, был ли за рулём живой человек. Это вопрос к Кану, не ко мне.", "grants": []}, {"id": "R136", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": [], "text": "— По протоколу угар. Машину РОВД не осматривал, только описал. Пока Кан не скажет, что не угар, смотреть её мне не на что.", "grants": [], "fallback": true}, {"id": "R137", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": [], "text": "Сеитова читает акт до конца.\n— В машину посадили мёртвым. Значит, машину смотреть надо. Где она, на стоянке РОВД? Дайте их протокол.", "grants": [], "fallback": true}, {"id": "R138", "on": "27ae146a-a05c-5e7a-84a1-899c35e883e4", "requires": [], "text": "— Следы с люка и лампы снимала я. Сравнение по картотеке Абишева. Второй набор в картотеке не значится. Дадите дактокарту человека — сравню.", "grants": [], "fallback": true}, {"id": "R139", "on": "0146fe89-1029-5d65-87bb-f750dfe7ad2d", "requires": [], "text": "— Задержанного откатаем. Пальцы, обувь. Сравнивать буду с подвалом. Материалы подвала мне на стол.", "grants": [], "fallback": true}, {"id": "R140", "on": "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "requires": [], "text": "— Ксерокопии купюр — это материал. Несите копии. И то, с чем сравнивать: купюры. Без второго сравнивать нечего.", "grants": [], "fallback": true}, {"id": "R141", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": [], "text": "— Сорок тысяч ушли. Номера кто-то переписывал? Если нет — сравнивать не с чем. Появятся купюры — ко мне.", "grants": [], "fallback": true}, {"id": "R142", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": [], "text": "— По свежему снегу в ночь на воскресенье. С тех пор оттепель. Там каша, колею уже не снять. Не моя графа — только время.", "grants": [], "fallback": true}, {"id": "R143", "on": "42ea83ef-f3ad-504f-99e0-da4ecb9fe57d", "requires": [], "text": "— Женские тридцать седьмого, под коркой слякоти. Дневные. Я так и писала. С её словами не спорят.", "grants": [], "fallback": true}, {"id": "R144", "on": "c4c95f03-86b0-5820-b9f4-736453e2dbef", "requires": [], "text": "— Разбитую фару сравнивать не с чем. Нет машины — нет экспертизы. Номер найдёте — посмотрю фару.", "grants": [], "fallback": true}, {"id": "R145", "on": "7188cb7d-2261-5a9c-8f78-e603caa6b31a", "requires": [], "text": "— Покупателя по следам не установишь. Фамилию назовёт — возьму пальцы, сравню с лампой.", "grants": [], "fallback": true}, {"id": "R146", "on": "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba", "requires": ["3772cdd6-1fe9-52d0-a268-3f82441220c7"], "text": "— Горный Гигант. Глина в арках как раз такая. Только грунт со двора мне никто не привёз. Сначала там побывайте.", "grants": [], "fallback": true}, {"id": "R147", "on": "cefb9e58-2cc4-5054-a43b-6216c7645217", "requires": [], "text": "Сеитова уже застёгивает сумку.\n— Санкция есть — еду с вами. Всё, что изымем, сразу ко мне. Обувь отдельно, деньги отдельно.", "grants": [], "fallback": true}, {"id": "R148", "on": "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "requires": ["3772cdd6-1fe9-52d0-a268-3f82441220c7"], "text": "— На машине Сартакова, в перчатках. Глина и чистый руль с этим сходятся. Добавить нечего.", "grants": [], "fallback": true}, {"id": "R211", "on": "60950128-af31-513e-b8de-bb87b02332cc", "requires": [], "text": "— Моё заключение. Будет обувь — сравню с калькой.", "grants": [], "fallback": true}, {"id": "R234", "on": "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba", "requires": ["c2c5ba62-e24e-523f-93bc-d8909b28e717", "3772cdd6-1fe9-52d0-a268-3f82441220c7"], "text": "— Горный Гигант. Глина в арках как раз такая. Грунт со двора Шмидтов — под навесом — возьму, сравню. Двор вы уже видели.", "grants": [], "supersedes": ["R146"], "fallback": true}, {"id": "R243", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": ["4f67be3f-f5f7-5ab5-bb69-611053df3042"], "text": "— Копии у меня. Купюры будут — сравню.", "grants": [], "supersedes": ["R141"], "fallback": true}, {"id": "R244", "on": "27ae146a-a05c-5e7a-84a1-899c35e883e4", "requires": ["9281d556-d163-5537-a0e2-e4cd2e635ba5"], "text": "— Второй набор — Бекенов. Справка у вас.", "grants": [], "supersedes": ["R138"], "fallback": true}, {"id": "R245", "on": "0146fe89-1029-5d65-87bb-f750dfe7ad2d", "requires": ["9281d556-d163-5537-a0e2-e4cd2e635ba5"], "text": "— Второй набор — Бекенов. Справка у вас.", "grants": [], "supersedes": ["R139"], "fallback": true}]'::jsonb, reactions = '{"b4e6a60f-b233-543e-b3b1-ae0a1427b6a1": "Сеитова раскладывает кальку на капоте служебного «уазика».\n— Два типа следов. Первый: мужская зимняя обувь, сорок третий размер. Протектор глубокий, на каблуке косой порез, около сантиметра. Следы под тонким слоем снега. Снег, по метеостанции, пошёл около часа ночи на воскресенье. Значит, следы ночные, до часу.\nВторой: женская обувь, тридцать седьмой. Эти под подмёрзшей коркой слякоти. Оставлены раньше, засветло, пока грязь была мягкая.\nИ борозды. Две, параллельные, со стороны водительской двери. Тело несли, ноги волочились. Чьи следы — не скажу. Размер скажу.", "46e78eb0-d057-5e5d-8a00-81457f8f3d20": "Сеитова не поднимает головы от стола.\n— Три тысячи. Тридцать купюр по сто. Сверила с ксерокопиями: серия, номер. У двух купюр надрыв на краю, на копии он тоже виден. Все тридцать есть в копиях выкупа. Совпадение полное. Протокол сравнения подпишу сегодня. Как они попали к нему за подкладку — это не ко мне.", "00b31a8e-e1ee-5474-a323-177b43b153d3": "Сеитова снимает перчатки.\n— Сорок третий. Протектор тот же. Порез на каблуке косой, около сантиметра, края совпадают со слепком у гаража. Ботинки мыли, но в шве у подошвы грязь осталась, на экспертизу хватит. Подошву сравнила с калькой по шести точкам. Совпали все шесть.\nМужские следы у гаража дачи оставлены этими ботинками. Кто был в ботинках — вопрос не ко мне.", "2d1a03f4-be7f-5007-8fe1-71c12d498c29": "Сеитова кладёт стопку протоколов рядом с листами ксерокопий.\n— Доллары из мешка с рисом. Пересчитала при понятых, номера переписала, сверила с копиями Ахметова лист за листом. Каждая купюра из тайника есть в копиях выкупа. Лишних нет. Чужих нет. Банковские резинки описаны. Рис описан отдельно.", "4f67be3f-f5f7-5ab5-bb69-611053df3042": "Вы кладёте рядом с конвертом «на похороны» показания Шнайдер: тот, кто принёс конверт, в субботу вечером был у дома Шмидтов.\nСеитова раскладывает купюры рядом с листами ксерокопий.\n— Конверт от матери покойного. Пять купюр по сто, новые, «с маленькой головой». Сверила номера. Все пять есть в копиях выкупа. Совпадение полное. Надпись карандашом «От Фархада — на похороны» внесла в протокол. Больше по конверту ничего.", "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44": "Сеитова вскрывает корпус пейджера над лотком, сливает мутную воду. Плату оставляет сохнуть на батарее. Наутро ставит новую батарейку.\n— Включился. Последнее принятое сообщение в памяти: четверг, двадцать первое, семнадцать тридцать пять. Позже ничего. В воде аппарат не принимает. Что на него слали после — это у оператора, к Абишеву. Арык у ворот сфотографировала. Где лежал — в протоколе.", "60950128-af31-513e-b8de-bb87b02332cc": "Сеитова раскладывает кальки.\n— Обувь. Нуртазин: форменные ботинки, сорок третий, протектор другого рисунка. Ахметов: сорок третий. Изъяла у него всё, что есть. Импортные туфли — подошва гладкая, кожаная. Зимние ботинки — протектор другой, пореза нет. Жумабаева: тридцать седьмой. Мужские следы у гаража ни одна из этих пар не оставила. Пары с порезом на каблуке среди того, что принесли, нет.", "5cdb3307-fe10-53c5-a365-6998256b7d7a": "Вы приносите Сеитовой конверт «на похороны» и напоминаете: пальцы того, кто его принёс, сняты с люка в подвале Шмидтов.\nСеитова кладёт пять купюр рядом с листами ксерокопий. Ведёт линейкой по строчкам.\n— Все пять есть в копиях выкупа. Серия, номер — совпадение полное. Протокол сравнения подпишу сегодня.", "c2c5ba62-e24e-523f-93bc-d8909b28e717": "Сеитова кладёт рядом две кальки.\n— Дактокарта Бекенова. Второй набор с крышки люка — его, по восьми признакам. Ахметова откатала тоже, он пришёл сам: с люком не совпадает. Кан смотрел кисти у обоих — свежих повреждений нет. Кровь у Бекенова — вторая группа, справка Кана. Абишев по ГАИ: водительского удостоверения и машины у Бекенова нет, говорит, что водить умеет. Свела всё в одну бумагу.", "43eaf70c-177d-516a-9ab2-7aecc9633e33": "Сеитова возвращается со стоянки Медеуского РОВД. На рукаве халата рыжая полоса глины.\n— Раз не угар, смотреть надо машину. Посмотрела. В колёсных арках жёлтая глина. Плотная, налипла слоем. Такая бывает на немощёных улицах частного сектора. В Горном Гиганте, например. На Кок-Тобе к даче асфальт и щебень, там такую не наберёшь.\nРуль: ни одного отпечатка. Ни чужого, ни хозяйского. Последним машину вёл человек в перчатках. Кто — не моя графа.", "a9b47e33-f5b4-57b9-9e16-1e41c38e7834": "Сеитова трёт сажу между пальцами, нюхает.\n— Свежая. Мотор работал часа три, не меньше, на холостых, при закрытых воротах. Бак, говорите, сухой? Сходится.\n(вытирает руку платком)\nТолько копоть не скажет, был ли за рулём живой человек. Это вопрос к Кану, не ко мне."}'::jsonb where id = 'd3ddcd6d-4093-5464-970c-de4ad3cb9af1';  -- Гульнара Сеитова
update characters set reaction_rules = '[{"id": "R02", "on": "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44", "requires": [], "text": "Абишев берёт пейджер двумя пальцами. С него капает.\n— Ну, этот своё отработал. А номер на крышке есть. Позвонил в пейджинговую, девочки там нормальные, журнал подняли. Значит, так. С вечера четверга до субботы на этот номер диктовали. Из офиса — «СРОЧНО ПЕРЕЗВОНИ», несколько раз. И от матери. В офисе говорят: не перезвонил ни разу.\nА прочитал он или нет — этого никто не скажет. Пейджер в одну сторону работает: оператор отправил, и всё. Выводы уж вы сами.", "grants": ["7ada2011-2720-5b69-8a9c-9291fdad70e9"]}, {"id": "R10", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": [], "text": "Абишев листает протокол РОВД.\n— Отключение света, значит. А было ли оно, РОВД проверять не стал. Ну ладно. Написал запрос диспетчеру районных электросетей по Кок-Тобе. Потом сам съездил: без печати бумагу не отдают. Вот. В субботу с девятнадцати ноль-ноль до двух ночи район Кок-Тобе обесточен. По графику.\nПро другие районы я не спрашивал: там на каждый район отдельная бумага. Так что света на даче не было. Тут РОВД прав.", "grants": ["9eedb06d-09c9-5fa6-b91f-46d7753f78b4"]}, {"id": "R11", "on": "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "requires": ["27ae146a-a05c-5e7a-84a1-899c35e883e4"], "text": "Абишев выслушивает. Стул под ним скрипит.\n— Пальцы на керосиновой лампе, в доме в Горном Гиганте. А сам он, говорит, сидел при свечке в «Орбите». Понял. «Орбиту» никто не запрашивал. Пишу отдельно. Сразу за пятницу и за субботу, чтобы второй раз не ездить.\nЧерез день на столе бумага с печатью.\n— Вот. Ни в пятницу, ни в субботу в «Орбите» не отключали. Ни по графику, ни аварийно. В субботу с семи вечера отключали только Кок-Тобе и Горный Гигант. Это справка. Выводы — ваши.", "grants": ["64b699fc-69d6-5bc3-ab81-b5a48df561bd"]}, {"id": "R12", "on": "e4e94374-000e-52e3-bb26-9bec42b1c55b", "requires": [], "text": "Абишев переписывает цифры с АОН на сигаретную пачку.\n— Суббота, пятнадцать тридцать. Хорошо, что у неё АОН на девяносто девять номеров. Был бы на двадцать — за два дня соболезнований этот бы уже вытеснило. По первым цифрам — частный сектор под горами. Ждите.\nЧерез час возвращается с листком.\n— Значит, так. Телефон зарегистрирован на Шмидта Г. Выбыл в ФРГ, на постоянное. Адрес — частный сектор в Горном Гиганте. Участковый тамошний говорит: дом пустой, продаётся по доверенности. А телефон не отключён. Выходит, звонили из пустого дома. На кого доверенность — это к нотариусу. А там неделя, не меньше.", "grants": ["f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba"]}, {"id": "R13", "on": "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "requires": [], "text": "— Номер, который ваш финансист с АОН запомнил? — Абишев кивает. — Бухгалтеры, они цифры помнят. Пробил через адресное бюро. Шмидт Г., выбыл в ФРГ на постоянное жительство. Частный сектор в Горном Гиганте. Участковый говорит: дом пустой, продаётся по доверенности. На кого — не знает, это к нотариусу. Телефон в доме не отключён. И с него, выходит, в субботу звонили.", "grants": ["f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba"]}, {"id": "R17", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba"], "text": "Абишев трёт глаза. Ночь не спал.\n— Пальцы с люка и с лампы. Гульнара сняла чисто, на копоти хорошо отпечаталось. Сравнивал вручную, по картотеке, всю ночь. Начал с тех, кто у вас в деле есть и на кого есть дактокарта.\nЕсть совпадение. Мамаджанов Фархад. Судим в девяносто четвёртом, таможенное дело.\nВторой набор с люка в картотеке не значится. Человек несудимый, на таких карточек нет.\nИ вот ещё. В учётном деле лежит медкарта из колонии. Группа крови — вторая. Это я так, к сведению.", "grants": ["27ae146a-a05c-5e7a-84a1-899c35e883e4"]}, {"id": "R20", "on": "be5c249c-d25f-5239-865f-5aef2088bc61", "requires": ["c4c95f03-86b0-5820-b9f4-736453e2dbef", "f725c4c5-f254-5c01-b718-3531a957102a"], "text": "Абишев вертит в руках пейджер охранника.\n— Логику понял. Пустой дом знали, и четверги знали. Пустой дом — это бумаги, нотариус. А что хозяин по четвергам без шофёра ездит — это люди. Это знали на базе. Сообщения он стёр. Только у пейджинговой свой журнал: что им диктуют, то они и записывают.\nКладёт перед вами листок, переписанный от руки.\n— Четверг, двадцать первое. Шестнадцать тридцать. Абонент Нуртазин. Текст: «ЧЕТВЕРГ В СИЛЕ? Ф.». Кто такой «Ф.» — оператор не спрашивает. В журнале этого нет.", "grants": ["c50332f2-fb14-5cff-9ea2-9581024ac2e3"]}, {"id": "R38", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "— Мамаджанов? Он у нас есть. Судим в девяносто четвёртом, таможня, дактокарта с тех пор лежит. — Абишев тянет с полки ящик картотеки. — Сравнивал вручную, полночи. Пальцы с крышки люка и с керосиновой лампы — его, Гульнара подтвердит. Второй набор с люка в картотеке не значится: человек несудимый. И раз уж я в его деле сидел: медкарта колонии, группа крови вторая. Это так, к сведению. В медицине я не понимаю.", "grants": ["27ae146a-a05c-5e7a-84a1-899c35e883e4"], "supersedes": ["R17"]}, {"id": "R48", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba"], "text": "— Подождите. Соседка видела его «Волгу» у дома Шмидтов в субботу вечером? А он вам говорил: сидел в «Орбите» при свечке. — Абишев роется в бумагах. — «Орбиту» никто не проверял. Сейчас. Заодно и пятницу спрошу, чтобы два раза не звонить.\nЗвонит. Ждёт. Записывает.\n— Диспетчер говорит: в «Орбите» ни в пятницу, ни в субботу отключений не было. Свет был. В субботу с семи вечера отключали только Кок-Тобе и Горный Гигант. Бумагу пришлют завтра. Знать вы это можете уже сегодня.", "grants": ["64b699fc-69d6-5bc3-ab81-b5a48df561bd"]}, {"id": "R51", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": [], "text": "Абишев тянется за сигаретами.\n— «Волга» с одной фарой? По вашему кругу запросил ИЦ и ГАИ. Мамаджанов Ф. — ГАЗ-24, «Волга», белая. Что у неё с фарами, ГАИ не пишет, в карточке такого нет. Ахметов — ВАЗ-2109, белая. Попросил гаишников глянуть у офиса: фары целы, обе. Жумабаева — «Таврия», красная. Нуртазин — личной машины нет, ездит на служебном «уазике» агентства. Белых, значит, две. Дальше смотрите сами.", "grants": ["d8f33493-fc81-5e50-af40-37d9500040b6"]}, {"id": "R57", "on": "b229ab87-5e5b-5f61-8a7b-18c17718e4cf", "requires": ["0a295d5f-e115-5c89-a26a-5992761304a0", "c4c95f03-86b0-5820-b9f4-736453e2dbef"], "text": "Абишев рисует таблицу на обороте старой ориентировки.\n— Даты свёл, раз все бумаги у меня. Чайхана, где охраннику долг списали, — девятое, суббота. «Волга» с одной фарой у ворот базы — четырнадцатое, четверг. «Месяц тебе, или сядешь» — шестнадцатое, суббота. Похищение — двадцать первое.\nТычет ручкой в первые две строки.\n— Вот эти две — раньше крика в кабинете. Больше тут ничего не написано. Остальное — ваше.", "grants": ["06da149b-c92c-54fa-a5f5-b78ff87dbc92"]}, {"id": "R58", "on": "be5c249c-d25f-5239-865f-5aef2088bc61", "requires": ["c4c95f03-86b0-5820-b9f4-736453e2dbef", "c2c5ba62-e24e-523f-93bc-d8909b28e717"], "text": "Абишев откладывает пейджер охранника.\n— Номер на наклейке есть. Позвонил в пейджинговую. Журнал за двадцать первое: шестнадцать тридцать, абонент Нуртазин, текст «ЧЕТВЕРГ В СИЛЕ? Ф.». Кто подписался «Ф.», в журнале не пишут. Это справка, не обвинение.", "grants": ["c50332f2-fb14-5cff-9ea2-9581024ac2e3"], "supersedes": ["R20"]}, {"id": "R61", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba"], "text": "— Высокий молодой парень вышел из «Волги» вместе с Мамаджановым? Значит, смотрим, кто у Мамаджанова в городе из молодых. — Абишев снимает с полки учётное дело девяносто четвёртого года, листает анкету. — Графа «родственники»: двоюродная сестра, Бекенова, Талгарский район. Дальше адресное бюро. По городу прописан один Бекенов оттуда. Олжас, двадцать два года. Временная прописка: общежитие у Зелёного базара, комната четыреста двенадцать. Племянник, выходит. Это фамилия и адрес. Остальное не ко мне.", "grants": ["6a92b637-cb0c-5bf4-8495-f503839bf08c"]}, {"id": "R62", "on": "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "requires": ["27ae146a-a05c-5e7a-84a1-899c35e883e4"], "text": "— Курьер на остановке: высокий, молодой, куртка, ушанка. И пальцы Мамаджанова в том подвале. Ну, значит, смотрим, кто у Мамаджанова в городе из молодых. — Абишев снова достаёт учётное дело девяносто четвёртого года. — Анкета, графа «родственники»: двоюродная сестра, Бекенова, Талгарский район. Адресное бюро: в городе временно прописан Бекенов Олжас, двадцать два года, оттуда же. Общежитие у Зелёного базара, комната четыреста двенадцать. Вот справка.", "grants": ["6a92b637-cb0c-5bf4-8495-f503839bf08c"]}, {"id": "R149", "on": "c4c95f03-86b0-5820-b9f4-736453e2dbef", "requires": [], "text": "Абишев вздыхает.\n— Белая двадцать четвёртая, одна фара. Номера нет. Белых «Волг» в ГАИ по городу — тысячи. Фару в учёт не пишут. Будут фамилии — проверю, на ком какая машина.", "grants": [], "fallback": true}, {"id": "R150", "on": "0a295d5f-e115-5c89-a26a-5992761304a0", "requires": [], "text": "— Крик в кабинете. Ни номера, ни адреса, ни даты для журнала. Запрос делать не по чему. Это справка, не обвинение, — а тут даже справки нет.", "grants": [], "fallback": true}, {"id": "R151", "on": "42ea83ef-f3ad-504f-99e0-da4ecb9fe57d", "requires": [], "text": "— Журнал дежурств — больничный. Там уже всё подтверждено, с подписью. Мне по моим учётам проверять нечего.", "grants": [], "fallback": true}, {"id": "R152", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": [], "text": "— Номер остался в определителе? Тогда мне нужен сам номер. Цифры с аппарата — и я его по адресному бюро подниму. Со слов цифры не возьмёшь.", "grants": [], "fallback": true}, {"id": "R153", "on": "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "requires": [], "text": "— «Орбиту» в электросетях запросить можно. Только с чего? Человек пришёл с соболезнованием, сказал, что сидел дома. Он у вас не фигурант. Дайте основание — запрошу.", "grants": [], "fallback": true}, {"id": "R154", "on": "009a36f7-b362-586d-8943-61cd46149c3c", "requires": [], "text": "— Судимость девяносто четвёртого — в картотеке есть, подтвердится. Только что судим, вы и так знаете. Под что запрос? Нужен вопрос: телефон, адрес, машина.", "grants": [], "fallback": true}, {"id": "R155", "on": "b229ab87-5e5b-5f61-8a7b-18c17718e4cf", "requires": [], "text": "— Чайхана, пейджер, даты. Даты я сложить могу. Только таблица из одних его слов — не таблица. Других показаний с датами мало.", "grants": [], "fallback": true}, {"id": "R156", "on": "0146fe89-1029-5d65-87bb-f750dfe7ad2d", "requires": [], "text": "— С таксофона звонили — по АТС такой звонок не поднимешь. Таксофон он и есть таксофон. По этим словам запрос делать не по чему.", "grants": [], "fallback": true}, {"id": "R157", "on": "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c", "requires": [], "text": "— Это очная ставка, не справка. В моих учётах нет ни кашля, ни «Беломора».", "grants": [], "fallback": true}, {"id": "R158", "on": "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "requires": [], "text": "— Частник, номер не помнит. Без номера машину не найти.", "grants": [], "fallback": true}, {"id": "R159", "on": "4e8b269e-8c91-5629-b60d-13930fa7e61e", "requires": [], "text": "— Чья «девятка», и так ясно. Где она ночью стояла, ГАИ не пишет. Проверять тут по учётам нечего.", "grants": [], "fallback": true}, {"id": "R160", "on": "7188cb7d-2261-5a9c-8f78-e603caa6b31a", "requires": [], "text": "— Покупатель без фамилии. Запрос делать не по чему. Назовёт фамилию — подниму по адресному бюро за час. Вывод сами.", "grants": [], "fallback": true}, {"id": "R161", "on": "e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c", "requires": [], "text": "— Кто ему руку поцарапал, в учётах не найдёшь. Руку пусть Кан смотрит.", "grants": [], "fallback": true}, {"id": "R162", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": [], "text": "— Группа — это медицина, к Кану. Вот если человек у нас в учёте — тогда и медкарту найду. Дайте фамилию.", "grants": [], "fallback": true}, {"id": "R163", "on": "3772cdd6-1fe9-52d0-a268-3f82441220c7", "requires": [], "text": "— Горный Гигант — это сотни дворов, улицы без названий. Без улицы и дома запрос не сделать.", "grants": [], "fallback": true}, {"id": "R164", "on": "3b4003bd-1d82-5ec7-b07b-4c54af3ac4c0", "requires": [], "text": "— Круг лиц — это не запрос. Фамилии будут — проверю по всем учётам. Вывод сами.", "grants": [], "fallback": true}, {"id": "R174", "on": "9281d556-d163-5537-a0e2-e4cd2e635ba5", "requires": [], "text": "— Четвёртый пункт мой: данные ГАИ по машинам. Остальное — Сеитова и Кан.\n(постукивает ручкой по строчке)\nМоё там всё верно. Вывод сами.", "grants": [], "fallback": true}, {"id": "R235", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "64b699fc-69d6-5bc3-ab81-b5a48df561bd"], "text": "— «Орбиту» я уже проверял. Свет там был и в пятницу, и в субботу. Справка у вас.", "grants": [], "supersedes": ["R48"]}, {"id": "R236", "on": "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "requires": ["27ae146a-a05c-5e7a-84a1-899c35e883e4", "64b699fc-69d6-5bc3-ab81-b5a48df561bd"], "text": "— «Орбиту» я уже проверял. Свет там был и в пятницу, и в субботу. Справка у вас.", "grants": [], "supersedes": ["R11"]}]'::jsonb, reactions = '{"1ac01ab0-e8f1-5009-9640-d18dfa4f5e44": "Абишев берёт пейджер двумя пальцами. С него капает.\n— Ну, этот своё отработал. А номер на крышке есть. Позвонил в пейджинговую, девочки там нормальные, журнал подняли. Значит, так. С вечера четверга до субботы на этот номер диктовали. Из офиса — «СРОЧНО ПЕРЕЗВОНИ», несколько раз. И от матери. В офисе говорят: не перезвонил ни разу.\nА прочитал он или нет — этого никто не скажет. Пейджер в одну сторону работает: оператор отправил, и всё. Выводы уж вы сами.", "43eaf70c-177d-516a-9ab2-7aecc9633e33": "Абишев листает протокол РОВД.\n— Отключение света, значит. А было ли оно, РОВД проверять не стал. Ну ладно. Написал запрос диспетчеру районных электросетей по Кок-Тобе. Потом сам съездил: без печати бумагу не отдают. Вот. В субботу с девятнадцати ноль-ноль до двух ночи район Кок-Тобе обесточен. По графику.\nПро другие районы я не спрашивал: там на каждый район отдельная бумага. Так что света на даче не было. Тут РОВД прав.", "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba": "Абишев выслушивает. Стул под ним скрипит.\n— Пальцы на керосиновой лампе, в доме в Горном Гиганте. А сам он, говорит, сидел при свечке в «Орбите». Понял. «Орбиту» никто не запрашивал. Пишу отдельно. Сразу за пятницу и за субботу, чтобы второй раз не ездить.\nЧерез день на столе бумага с печатью.\n— Вот. Ни в пятницу, ни в субботу в «Орбите» не отключали. Ни по графику, ни аварийно. В субботу с семи вечера отключали только Кок-Тобе и Горный Гигант. Это справка. Выводы — ваши.", "e4e94374-000e-52e3-bb26-9bec42b1c55b": "Абишев переписывает цифры с АОН на сигаретную пачку.\n— Суббота, пятнадцать тридцать. Хорошо, что у неё АОН на девяносто девять номеров. Был бы на двадцать — за два дня соболезнований этот бы уже вытеснило. По первым цифрам — частный сектор под горами. Ждите.\nЧерез час возвращается с листком.\n— Значит, так. Телефон зарегистрирован на Шмидта Г. Выбыл в ФРГ, на постоянное. Адрес — частный сектор в Горном Гиганте. Участковый тамошний говорит: дом пустой, продаётся по доверенности. А телефон не отключён. Выходит, звонили из пустого дома. На кого доверенность — это к нотариусу. А там неделя, не меньше.", "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e": "— Номер, который ваш финансист с АОН запомнил? — Абишев кивает. — Бухгалтеры, они цифры помнят. Пробил через адресное бюро. Шмидт Г., выбыл в ФРГ на постоянное жительство. Частный сектор в Горном Гиганте. Участковый говорит: дом пустой, продаётся по доверенности. На кого — не знает, это к нотариусу. Телефон в доме не отключён. И с него, выходит, в субботу звонили.", "c2c5ba62-e24e-523f-93bc-d8909b28e717": "Абишев трёт глаза. Ночь не спал.\n— Пальцы с люка и с лампы. Гульнара сняла чисто, на копоти хорошо отпечаталось. Сравнивал вручную, по картотеке, всю ночь. Начал с тех, кто у вас в деле есть и на кого есть дактокарта.\nЕсть совпадение. Мамаджанов Фархад. Судим в девяносто четвёртом, таможенное дело.\nВторой набор с люка в картотеке не значится. Человек несудимый, на таких карточек нет.\nИ вот ещё. В учётном деле лежит медкарта из колонии. Группа крови — вторая. Это я так, к сведению.", "be5c249c-d25f-5239-865f-5aef2088bc61": "Абишев вертит в руках пейджер охранника.\n— Логику понял. Пустой дом знали, и четверги знали. Пустой дом — это бумаги, нотариус. А что хозяин по четвергам без шофёра ездит — это люди. Это знали на базе. Сообщения он стёр. Только у пейджинговой свой журнал: что им диктуют, то они и записывают.\nКладёт перед вами листок, переписанный от руки.\n— Четверг, двадцать первое. Шестнадцать тридцать. Абонент Нуртазин. Текст: «ЧЕТВЕРГ В СИЛЕ? Ф.». Кто такой «Ф.» — оператор не спрашивает. В журнале этого нет.", "f725c4c5-f254-5c01-b718-3531a957102a": "— Подождите. Соседка видела его «Волгу» у дома Шмидтов в субботу вечером? А он вам говорил: сидел в «Орбите» при свечке. — Абишев роется в бумагах. — «Орбиту» никто не проверял. Сейчас. Заодно и пятницу спрошу, чтобы два раза не звонить.\nЗвонит. Ждёт. Записывает.\n— Диспетчер говорит: в «Орбите» ни в пятницу, ни в субботу отключений не было. Свет был. В субботу с семи вечера отключали только Кок-Тобе и Горный Гигант. Бумагу пришлют завтра. Знать вы это можете уже сегодня.", "b229ab87-5e5b-5f61-8a7b-18c17718e4cf": "Абишев рисует таблицу на обороте старой ориентировки.\n— Даты свёл, раз все бумаги у меня. Чайхана, где охраннику долг списали, — девятое, суббота. «Волга» с одной фарой у ворот базы — четырнадцатое, четверг. «Месяц тебе, или сядешь» — шестнадцатое, суббота. Похищение — двадцать первое.\nТычет ручкой в первые две строки.\n— Вот эти две — раньше крика в кабинете. Больше тут ничего не написано. Остальное — ваше."}'::jsonb where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';  -- Ринат Абишев
update characters set reaction_rules = '[{"id": "R01", "on": "e34a96b0-5d0e-5414-9ef3-048071ef84ed", "requires": [], "text": "Кан снимает очки. Протирает полой халата. Долго.\n— Не угорел он, голубчик. Угоревший — он розовый. А этот синий, одутловатый, в глазах точечные кровоизлияния. Удушение, шею сдавили. В машину его посадили уже мёртвым. Смерть — суббота, около двадцати двух. Ну, час туда-сюда.\nДальше. На запястьях слабые следы: связывали поверх рукавов. Щетина дня два, обезвоживание, голодал. Двое суток он где-то был. И не по своей воле.\nИ вот ещё. Под ногтями кровь. У него первая группа. А под ногтями вторая. Чья — это уже не ко мне.", "grants": ["54bf13bc-3525-5eec-9441-609d8ee21f59"]}, {"id": "R29", "on": "abc6fac8-abbd-5589-b6b5-958cd368e7fe", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59", "cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "Кабинет. Двое понятых. Кан просит задержанного положить левую руку на стол и сам разматывает бинт. Виток за витком.\n— Ожога нет. Ни пузыря, ни пятна.\nБерёт лупу.\n— Царапины. Три, параллельные, края дугой. Это ногти, человеческие. От животного следы другие, я их видел достаточно. Давность — четверо-шестеро суток, заживают. Вечеру субботы не противоречит.\nТеперь второе. По медкарте колонии группа вторая. Под ногтями покойного тоже вторая. Только вторая — у каждого третьего в городе, сама по себе она ничего не доказывает. Царапины отдельно, группа отдельно. Я описываю, что вижу. Складывать будете вы.", "grants": ["7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3"]}, {"id": "R49", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "Кан надевает очки, читает с листа.\n— Таблица. Запросил медкарты и учётные дела на всех, кто у вас в деле с фамилией и адресом. Мамаджанов — вторая, по медкарте колонии. Ахметов — вторая. Нуртазин — первая, из личного дела МВД, он в милиции служил. Жумабаева — третья. Под ногтями — вторая. Двоим подходит, двоим нет. Группа крови — это не отпечаток пальца. Исключить человека она может. Назвать — нет.", "grants": ["b177dd97-7391-5f5e-8308-72a1073516c2"]}, {"id": "R52", "on": "e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c", "requires": ["cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "Валентина Петровна вспомнила: в воскресенье рука у него была расцарапана. «Собака на базаре».\nКан кивает. В кабинете, при понятых, разматывает бинт на кисти задержанного.\n— Ожога под бинтом нет. Царапины: три, параллельные, края дугой. Ногти, человеческие. От собаки так не бывает: от собаки покусы, когти, след другой. Давность — четверо-шестеро суток, заживают. С вечером субботы совместимо. Группа у него по медкарте колонии вторая. Под ногтями покойного тоже вторая. Я описываю кисть. Выводы делайте сами.", "grants": ["7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3"]}, {"id": "R53", "on": "b177dd97-7391-5f5e-8308-72a1073516c2", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "Кан дописывает строку в свою таблицу.\n— Бекенова, задержанного, привели с утра. Кровь взял: вторая группа. Кисти посмотрел у него и, для порядка, у Ахметова. Тот пришёл сам, рукава засучил без разговоров. Свежих повреждений нет ни у того, ни у другого. Гульнара сверила дактокарту Бекенова со вторым набором с люка — его. С пальцами Ахметова тот набор не совпал. Ринат по ГАИ добавил: прав и машины у Бекенова нет. Водить, говорит, умеет. Вот. Я описываю. Складываете вы.", "grants": ["9281d556-d163-5537-a0e2-e4cd2e635ba5"]}, {"id": "R126", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": [], "text": "Кан смотрит выписку поверх очков. Откладывает.\n— Угорел… Это РОВД так решил, голубчик. Без вскрытия ни я, ни они этого не знаем. Тело у меня в журнале с прочерком. Направьте — посмотрю.", "grants": [], "fallback": true}, {"id": "R127", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"], "text": "— Видел я эту бумагу. Угара там нет, голубчик. Всё, что есть, в моём заключении.", "grants": [], "fallback": true}, {"id": "R128", "on": "27ae146a-a05c-5e7a-84a1-899c35e883e4", "requires": [], "text": "Кан протирает очки полой халата.\n— Вторая группа. Под ногтями тоже вторая. Только поверьте старику: вторая группа у каждого третьего в городе. Группой можно исключить. Назвать человека группой нельзя.", "grants": [], "fallback": true}, {"id": "R129", "on": "0146fe89-1029-5d65-87bb-f750dfe7ad2d", "requires": [], "text": "— Раз задержан, приведите. Кровь возьму, руки посмотрю. Только сравнивать надо не на глаз, а с моей справкой по группам. Её и несите.", "grants": [], "fallback": true}, {"id": "R130", "on": "4e8b269e-8c91-5629-b60d-13930fa7e61e", "requires": [], "text": "— Около десяти, голубчик. Плюс-минус час, точнее по трупу не скажу. А кто в это время курил на лестнице — это не ко мне.", "grants": [], "fallback": true}, {"id": "R131", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": [], "text": "— Двадцать три двадцать, говорите… Смерть по моему заключению около двадцати двух. Через час его уже могли везти. Могли и не везти. Это я по трупу не определю.", "grants": [], "fallback": true}, {"id": "R132", "on": "42ea83ef-f3ad-504f-99e0-da4ecb9fe57d", "requires": [], "text": "— Наркоз в двадцать три десять? Это к анестезиологам, голубчик. Я скажу одно: умер он около десяти вечера. А где она была — это журналы, не морг.", "grants": [], "fallback": true}, {"id": "R133", "on": "7ada2011-2720-5b69-8a9c-9291fdad70e9", "requires": [], "text": "Кан кивает.\n— С моим сходится. Щетина двое суток, обезвоживание. С четверга его где-то держали. Больше по пейджеру я вам не скажу.", "grants": [], "fallback": true}, {"id": "R134", "on": "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "requires": [], "text": "— Сдавление шеи, тело в машину посадили мёртвым. С моим заключением сходится. Добавить нечего, голубчик.", "grants": [], "fallback": true}, {"id": "R135", "on": "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c", "requires": [], "text": "— Через мешок узнал? По кашлю, по запаху — бывает, голубчик. Это не медицина, это память. Заключения тут я не дам.", "grants": [], "fallback": true}, {"id": "R209", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": [], "text": "— Это моё заключение, голубчик. Чьё там под ногтями — несите людей, кровь возьму.", "grants": [], "fallback": true}, {"id": "R210", "on": "b177dd97-7391-5f5e-8308-72a1073516c2", "requires": [], "text": "— Моя таблица, голубчик. Группа исключает, не называет. Нового без задержанных не скажу.", "grants": [], "fallback": true}, {"id": "R246", "on": "0146fe89-1029-5d65-87bb-f750dfe7ad2d", "requires": ["9281d556-d163-5537-a0e2-e4cd2e635ba5"], "text": "— Бекенова я смотрел, голубчик. Вторая группа, кисти чистые. В справке всё.", "grants": [], "supersedes": ["R129"], "fallback": true}]'::jsonb, reactions = '{"e34a96b0-5d0e-5414-9ef3-048071ef84ed": "Кан снимает очки. Протирает полой халата. Долго.\n— Не угорел он, голубчик. Угоревший — он розовый. А этот синий, одутловатый, в глазах точечные кровоизлияния. Удушение, шею сдавили. В машину его посадили уже мёртвым. Смерть — суббота, около двадцати двух. Ну, час туда-сюда.\nДальше. На запястьях слабые следы: связывали поверх рукавов. Щетина дня два, обезвоживание, голодал. Двое суток он где-то был. И не по своей воле.\nИ вот ещё. Под ногтями кровь. У него первая группа. А под ногтями вторая. Чья — это уже не ко мне.", "abc6fac8-abbd-5589-b6b5-958cd368e7fe": "Кабинет. Двое понятых. Кан просит задержанного положить левую руку на стол и сам разматывает бинт. Виток за витком.\n— Ожога нет. Ни пузыря, ни пятна.\nБерёт лупу.\n— Царапины. Три, параллельные, края дугой. Это ногти, человеческие. От животного следы другие, я их видел достаточно. Давность — четверо-шестеро суток, заживают. Вечеру субботы не противоречит.\nТеперь второе. По медкарте колонии группа вторая. Под ногтями покойного тоже вторая. Только вторая — у каждого третьего в городе, сама по себе она ничего не доказывает. Царапины отдельно, группа отдельно. Я описываю, что вижу. Складывать будете вы.", "54bf13bc-3525-5eec-9441-609d8ee21f59": "Кан надевает очки, читает с листа.\n— Таблица. Запросил медкарты и учётные дела на всех, кто у вас в деле с фамилией и адресом. Мамаджанов — вторая, по медкарте колонии. Ахметов — вторая. Нуртазин — первая, из личного дела МВД, он в милиции служил. Жумабаева — третья. Под ногтями — вторая. Двоим подходит, двоим нет. Группа крови — это не отпечаток пальца. Исключить человека она может. Назвать — нет.", "e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c": "Валентина Петровна вспомнила: в воскресенье рука у него была расцарапана. «Собака на базаре».\nКан кивает. В кабинете, при понятых, разматывает бинт на кисти задержанного.\n— Ожога под бинтом нет. Царапины: три, параллельные, края дугой. Ногти, человеческие. От собаки так не бывает: от собаки покусы, когти, след другой. Давность — четверо-шестеро суток, заживают. С вечером субботы совместимо. Группа у него по медкарте колонии вторая. Под ногтями покойного тоже вторая. Я описываю кисть. Выводы делайте сами.", "b177dd97-7391-5f5e-8308-72a1073516c2": "Кан дописывает строку в свою таблицу.\n— Бекенова, задержанного, привели с утра. Кровь взял: вторая группа. Кисти посмотрел у него и, для порядка, у Ахметова. Тот пришёл сам, рукава засучил без разговоров. Свежих повреждений нет ни у того, ни у другого. Гульнара сверила дактокарту Бекенова со вторым набором с люка — его. С пальцами Ахметова тот набор не совпал. Ринат по ГАИ добавил: прав и машины у Бекенова нет. Водить, говорит, умеет. Вот. Я описываю. Складываете вы."}'::jsonb where id = 'a6c62ec0-5ff9-53a5-b9a2-20898741074b';  -- Юрий Николаевич Кан
update characters set reaction_rules = '[{"id": "R23", "on": "34e1077a-bcc2-53ac-90e8-702d023d03c7", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59", "b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "Бейсенов долго смотрит фототаблицу и схему следов. Постукивает карандашом.\n— Скажу, как это выглядит с точки зрения криминологии. Заложника, за которого получен выкуп, обычно отпускают. Мёртвый заложник похитителю ни к чему, это лишний риск. После выкупа убивают, как правило, в одном случае: похититель боится, что его опознают. То есть жертва его знала.\nДальше. Инсценировку делал человек, который знал дачу, знал привычки покойного и рассчитывал, что семья промолчит. Это не случайные люди. Это круг: друзья семьи, партнёры, бывшие супруги, охрана.\nИмён я не называю. Это закономерность, не больше.", "grants": ["3b4003bd-1d82-5ec7-b07b-4c54af3ac4c0"]}, {"id": "R56", "on": "0a295d5f-e115-5c89-a26a-5992761304a0", "requires": ["c4c95f03-86b0-5820-b9f4-736453e2dbef", "b229ab87-5e5b-5f61-8a7b-18c17718e4cf"], "text": "Бейсенов раскладывает на столе четыре листка с показаниями. По датам, слева направо. Карандашом — по каждому.\n— Давайте по хронологии. Девятое ноября, суббота: разговор в чайхане. Наводчику предлагают списать долг за сведения о четвергах. Четырнадцатое, четверг: белая «Волга» с разбитой фарой стоит у ворот базы. Шестнадцатое, суббота: покойный уличает своего финансиста, «месяц тебе, или сядешь». Двадцать первое: похищение.\nПодготовка началась за неделю до того, как у финансиста появилась причина. А как правило, бывает наоборот: сначала мотив, потом план. Имён я не называю. Это порядок дат.", "grants": ["06da149b-c92c-54fa-a5f5-b78ff87dbc92"]}, {"id": "R165", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": [], "text": "Бейсенов постукивает карандашом по выписке.\n— Протокол фиксирует версию, а не факт. Пока нет вскрытия, профиль строить не по чему.", "grants": [], "fallback": true}, {"id": "R166", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": [], "text": "— Удушение, связывание, двое суток. Позвольте не спешить. Мне нужно понять, что происходило эти двое суток. Требовали что-нибудь у семьи?", "grants": [], "fallback": true}, {"id": "R167", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"], "text": "— Похищение с выкупом. Выкуп получен, заложник мёртв. Как правило, это многое говорит. Но мне нужна картина места: как и в каком виде его оставили в гараже.", "grants": [], "fallback": true}, {"id": "R168", "on": "0a295d5f-e115-5c89-a26a-5992761304a0", "requires": [], "text": "— Мотив налицо. Но мотив без дат — половина картины. Когда начали готовить — вот что важно. Сложите даты.", "grants": [], "fallback": true}, {"id": "R169", "on": "b229ab87-5e5b-5f61-8a7b-18c17718e4cf", "requires": [], "text": "— Позвольте: здесь есть дата начала подготовки. Это ценно. Но одна дата — не хронология. Нужны другие, с ними и сравним.", "grants": [], "fallback": true}, {"id": "R170", "on": "c4c95f03-86b0-5820-b9f4-736453e2dbef", "requires": [], "text": "— Регулярность — первое, что изучает похититель. Кто знал расписание — вопрос к вам, не ко мне. Я говорю категориями.", "grants": [], "fallback": true}, {"id": "R171", "on": "0146fe89-1029-5d65-87bb-f750dfe7ad2d", "requires": [], "text": "— «Я сам всё придумал». Позвольте сформулировать: это фраза, которую проверяют, а не принимают. Проверять — фактами. Профиль здесь не поможет.", "grants": [], "fallback": true}, {"id": "R172", "on": "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c", "requires": [], "text": "— Это уже показания против конкретного лица. Здесь моя работа закончена. Имён я не называю.", "grants": [], "fallback": true}, {"id": "R173", "on": "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "requires": ["3b4003bd-1d82-5ec7-b07b-4c54af3ac4c0"], "text": "— В типичном случае так и бывает: убивают, когда боятся опознания. Это я вам говорил. Остальное — дело следствия.", "grants": [], "fallback": true}]'::jsonb, reactions = '{"34e1077a-bcc2-53ac-90e8-702d023d03c7": "Бейсенов долго смотрит фототаблицу и схему следов. Постукивает карандашом.\n— Скажу, как это выглядит с точки зрения криминологии. Заложника, за которого получен выкуп, обычно отпускают. Мёртвый заложник похитителю ни к чему, это лишний риск. После выкупа убивают, как правило, в одном случае: похититель боится, что его опознают. То есть жертва его знала.\nДальше. Инсценировку делал человек, который знал дачу, знал привычки покойного и рассчитывал, что семья промолчит. Это не случайные люди. Это круг: друзья семьи, партнёры, бывшие супруги, охрана.\nИмён я не называю. Это закономерность, не больше.", "0a295d5f-e115-5c89-a26a-5992761304a0": "Бейсенов раскладывает на столе четыре листка с показаниями. По датам, слева направо. Карандашом — по каждому.\n— Давайте по хронологии. Девятое ноября, суббота: разговор в чайхане. Наводчику предлагают списать долг за сведения о четвергах. Четырнадцатое, четверг: белая «Волга» с разбитой фарой стоит у ворот базы. Шестнадцатое, суббота: покойный уличает своего финансиста, «месяц тебе, или сядешь». Двадцать первое: похищение.\nПодготовка началась за неделю до того, как у финансиста появилась причина. А как правило, бывает наоборот: сначала мотив, потом план. Имён я не называю. Это порядок дат."}'::jsonb where id = '11b90ca2-3c48-573f-95ac-041cf0635f90';  -- Аскар Бейсенов
update characters set reaction_rules = '[{"id": "R04", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": [], "text": "Виктор мнёт кепку. Смотрит не на протокол, а на гараж.\n— Угорел, написали... (пауза)\nЯ вам так скажу. По четвергам он меня в пять отпускал. Всегда. «Витя, свободен, я сам». И сюда, на дачу. Один. Это после развода повелось.\nДа все знали. Офис, на КПП ребята. Кто угодно.\n(пауза) И вот ещё. В позапрошлый четверг. Четырнадцатого. Выезжаю с базы — у ворот «Волга». Двадцать четвёртая, белая. Левая фара разбита, не горит.\nМужик за рулём сидит, курит. На ворота смотрит.\nНомер не запомнил, темно было. А фару запомнил. Я машины лучше людей помню.", "grants": ["c4c95f03-86b0-5820-b9f4-736453e2dbef"]}, {"id": "R05", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"], "text": "Виктор долго молчит. Кепку в руках не мнёт — держит.\n— Задушили, значит...\nНу тогда скажу. Я не стукач. Но раз такое дело.\nВ субботу, шестнадцатого. За пять дней до того четверга. Сижу в приёмной, дверь в кабинет неплотно закрыта.\nИгорь на Данияра орёт. Я его таким не слышал. Никогда.\n«Месяц тебе, или сядешь». Слово в слово.\nДанияр выходит — белый. Папку к груди прижал.\nА про что это — не знаю. Я в бумаги не лезу. Моё дело — баранка.", "grants": ["0a295d5f-e115-5c89-a26a-5992761304a0"]}, {"id": "R45", "on": "b4e6a60f-b233-543e-b3b1-ae0a1427b6a1", "requires": [], "text": "Виктор стоит у ворот гаража. Внутрь не заходит.\n— Я его полтора года возил. Каждый день.\nКроме четверга. В пять — «свободен, Витя». И сам за руль. И сюда, наверх. Один.\nПосле развода так стало. На базе все знали. На КПП ему шлагбаум заранее поднимали.\n(пауза) А ещё... В позапрошлый четверг, четырнадцатого, у ворот базы «Волга» стояла. Белая, двадцать четвёртая. Левая фара разбита.\nМужик сидит, курит. На ворота смотрит.\nЯ тогда подумал — клиента ждёт. Ну, частник. А теперь не знаю, что и думать.", "grants": ["c4c95f03-86b0-5820-b9f4-736453e2dbef"]}, {"id": "R68", "on": "a9b47e33-f5b4-57b9-9e16-1e41c38e7834", "requires": [], "text": "Виктор смотрит на пятно, отворачивается.\n— Прогревать он любил, да. Минут пять, десять. Но во дворе! Ворота настежь. Он гаража боялся, говорил: душегубка.\nЧтобы он сам ворота закрыл и сидел... Нет. Не он это.", "grants": []}, {"id": "R122", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": [], "text": "Виктор дочитывает. Кепку мнёт.\n— Одна фара. Правая горит, левая нет?\n(пауза)\n— Двадцать четвёртая, белая. Это она. У базы в четверг стояла, я ж говорил. Мужик курил, на ворота смотрел.\n— Кто такой — не знаю. Я машины помню. Людей — нет.", "grants": [], "fallback": true}, {"id": "R123", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": [], "text": "— В Бишкек… — Виктор долго молчит. — Мне так и сказали. Уехал, мол, Витя, отдыхай.\n(мнёт кепку)\n— Я и отдыхал. Таксовал. А он в это время…\n— Ну, Валентина Петровна. Ну правильно. Кто я такой, чтоб мне говорить. Водила.", "grants": [], "fallback": true}, {"id": "R247", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59", "c4c95f03-86b0-5820-b9f4-736453e2dbef"], "text": "Виктор долго молчит. Кепку в руках не мнёт — держит.\n— Задушили, значит...\nНу тогда скажу. Я не стукач. Но раз такое дело.\nВ субботу, шестнадцатого. За пять дней до того четверга. Сижу в приёмной, дверь в кабинет неплотно закрыта.\nИгорь на Данияра орёт. Я его таким не слышал. Никогда.\n«Месяц тебе, или сядешь». Слово в слово.\nДанияр выходит — белый. Папку к груди прижал.\nА про что это — не знаю. Я в бумаги не лезу. Моё дело — баранка.", "grants": [], "supersedes": ["R04", "R05"]}]'::jsonb, reactions = '{"43eaf70c-177d-516a-9ab2-7aecc9633e33": "Виктор мнёт кепку. Смотрит не на протокол, а на гараж.\n— Угорел, написали... (пауза)\nЯ вам так скажу. По четвергам он меня в пять отпускал. Всегда. «Витя, свободен, я сам». И сюда, на дачу. Один. Это после развода повелось.\nДа все знали. Офис, на КПП ребята. Кто угодно.\n(пауза) И вот ещё. В позапрошлый четверг. Четырнадцатого. Выезжаю с базы — у ворот «Волга». Двадцать четвёртая, белая. Левая фара разбита, не горит.\nМужик за рулём сидит, курит. На ворота смотрит.\nНомер не запомнил, темно было. А фару запомнил. Я машины лучше людей помню.", "b4e6a60f-b233-543e-b3b1-ae0a1427b6a1": "Виктор стоит у ворот гаража. Внутрь не заходит.\n— Я его полтора года возил. Каждый день.\nКроме четверга. В пять — «свободен, Витя». И сам за руль. И сюда, наверх. Один.\nПосле развода так стало. На базе все знали. На КПП ему шлагбаум заранее поднимали.\n(пауза) А ещё... В позапрошлый четверг, четырнадцатого, у ворот базы «Волга» стояла. Белая, двадцать четвёртая. Левая фара разбита.\nМужик сидит, курит. На ворота смотрит.\nЯ тогда подумал — клиента ждёт. Ну, частник. А теперь не знаю, что и думать.", "a9b47e33-f5b4-57b9-9e16-1e41c38e7834": "Виктор смотрит на пятно, отворачивается.\n— Прогревать он любил, да. Минут пять, десять. Но во дворе! Ворота настежь. Он гаража боялся, говорил: душегубка.\nЧтобы он сам ворота закрыл и сидел... Нет. Не он это."}'::jsonb where id = '54b23338-3cf2-5d0a-99c4-91c0de226522';  -- Виктор Гринько
update characters set reaction_rules = '[{"id": "R06", "on": "60950128-af31-513e-b8de-bb87b02332cc", "requires": [], "text": "Алия смотрит на снимок следа. Коротко смеётся. Зло.\n— Тридцать седьмой. Мой.\nЛадно. Была.\nВ пятницу. В три часа дня. Специально выбрала, когда он на работе.\nКлючи старые, на одной связке остались. Замки он так и не сменил. Жадность.\nЗабрала папку о приватизации. Для адвоката, для иска.\n(пауза) Гараж был пустой. Машины не было. Никого не было.\nА в субботу — с восьми вечера до восьми утра дежурство. В одиннадцать десять я давала наркоз, экстренная. Журнал дежурств, протокол с моей подписью.\nПроверяйте.\nЯ его хотела засудить. Не убить.", "grants": ["42ea83ef-f3ad-504f-99e0-da4ecb9fe57d"]}, {"id": "R116", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": [], "text": "Алия читает быстро. Профессионально. Сначала выводы.\n— Механическая асфиксия. Окиси углерода нет. В машину посадили мёртвым.\n(пауза)\n— Я ему десять лет говорила: угоришь. А его задушили. — Возвращает лист. — Под ногтями чужая кровь? Мою берите. Пожалуйста. Хоть сейчас.", "grants": [], "fallback": true}, {"id": "R117", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": [], "text": "— Даше? — Алия поднимает глаза. — Они грозили Даше?\n(встаёт)\n— И мне никто ни слова. Сорок тысяч собирали. В Бишкек он уехал. А я — мать. Мне — ни слова!\n(пауза. Тише)\n— Валентина Петровна. Всю жизнь одно и то же: всё сама, всё молча. Вот и домолчались.", "grants": [], "fallback": true}, {"id": "R118", "on": "e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c", "requires": [], "text": "Алия читает. На словах «Береги Дашу» лицо у неё белеет.\n— Он назвал мою дочь. По имени.\n(пауза)\n— Фархад-ака. Даша у него на коленях сидела. — Голос садится. — Где он сейчас? Скажите мне, где он сейчас.", "grants": [], "fallback": true}, {"id": "R204", "on": "b177dd97-7391-5f5e-8308-72a1073516c2", "requires": [], "text": "Алия пробегает глазами столбик.\n— Третья. Моя, правильно. — Возвращает лист. — Я вам сразу сказала: берите кровь. Под ногтями вторая. Значит, не я. Дальше сами.", "grants": [], "fallback": true}, {"id": "R205", "on": "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "requires": [], "text": "Алия дочитывает. Губы белые.\n— Фархад-ака. Своими руками. — Пауза. — Даше я скажу сама. Не вы.", "grants": [], "fallback": true}, {"id": "R206", "on": "7a9bdd9a-4323-5342-a3bd-24301a6d6e88", "requires": [], "text": "— Тридцать седьмой — мой, я вам и так сказала. Мужские следы ищите у мужчин.", "grants": [], "fallback": true}]'::jsonb, reactions = '{"60950128-af31-513e-b8de-bb87b02332cc": "Алия смотрит на снимок следа. Коротко смеётся. Зло.\n— Тридцать седьмой. Мой.\nЛадно. Была.\nВ пятницу. В три часа дня. Специально выбрала, когда он на работе.\nКлючи старые, на одной связке остались. Замки он так и не сменил. Жадность.\nЗабрала папку о приватизации. Для адвоката, для иска.\n(пауза) Гараж был пустой. Машины не было. Никого не было.\nА в субботу — с восьми вечера до восьми утра дежурство. В одиннадцать десять я давала наркоз, экстренная. Журнал дежурств, протокол с моей подписью.\nПроверяйте.\nЯ его хотела засудить. Не убить."}'::jsonb where id = '96e916c8-7fd0-5edc-a4fe-1a6aeda231bf';  -- Алия Сартакова (Жумабаева)
update characters set reaction_rules = '[{"id": "R08", "on": "e4e94374-000e-52e3-bb26-9bec42b1c55b", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"], "text": "Валентина Петровна смотрит на красные цифры АОН. Потом на свой блокнот.\n— Игорь поставил. Чтобы я знала, кто звонит. Ну вот. Знаю. — Садится, спинки стула не касается. — В четверг. Около девяти. Из автомата. Шестьдесят тысяч долларов. Пойдёте в милицию — Дашу не увидите. — Пауза. — Мы с Данияром собрали сорок. Больше не было. Не было больше.\nВ субботу, в половине четвёртого, ещё раз. Вот этот номер. Данияр рядом стоял, видел. Он отвёз деньги. Вернулся. И мы сидели. С половины восьмого до половины второго, здесь, у телефона. Ждали. — Нажимает кнопку, цифры гаснут. — Он так радовался этой коробочке. «Мама, теперь ты всё будешь знать».", "grants": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "group": "group-1", "repeat_text": "«Я вам уже всё рассказала. Больше мне добавить нечего»."}, {"id": "R09", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": ["1ac01ab0-e8f1-5009-9640-d18dfa4f5e44"], "text": "Вы кладёте перед ней заключение Кана и пейджер из арыка. Говорите: если вам угрожают, молчание никого не защитит. Защитить может только милиция.\nНа кухне перестают звенеть посудой.\n— Я тридцать лет учила детей говорить правду. Тридцать лет. А сама… — Долгая пауза. — Хорошо. Хорошо. Четверг, около девяти. Автомат. Шестьдесят тысяч. И если в милицию — Дашу мы больше не увидим. — Сбивается. — Мы с Данияром собрали сорок. Виктору я сказала: Игорь в Бишкеке. Суббота… половина четвёртого. Второй звонок, номер в АОН остался. Данияр отвёз деньги. Вернулся. С половины восьмого до половины второго был со мной. Ждали. — Голос ломается. — Я молчала из-за Даши. Из-за Даши.", "grants": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "group": "group-1", "repeat_text": "«Я вам уже всё рассказала. Больше мне добавить нечего»."}, {"id": "R46", "on": "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44", "requires": ["e4e94374-000e-52e3-bb26-9bec42b1c55b"], "text": "Валентина Петровна берёт пейджер. Смотрит на АОН. На блокнот, где цифры её почерком.\n— Его пейджер. В арыке, у ворот… Он не уезжал в Бишкек. — Пауза. — Это я придумала. В пятницу утром позвонила Виктору: Игорь в Бишкеке, вы свободны. Он поверил. Он мне всегда верит. — Дальше коротко, как диктант диктует: — Четверг, девять вечера. Автомат. Шестьдесят тысяч, иначе внучка. С Данияром собрали сорок. Суббота, пятнадцать тридцать, вот этот номер. Данияр отвёз деньги, вернулся. С половины восьмого до половины второго был со мной. — Кладёт пейджер. — Скажите Виктору сами. Я не смогу… Я ему в глаза не смогу.", "grants": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "group": "group-1", "repeat_text": "«Я вам уже всё рассказала. Больше мне добавить нечего»."}, {"id": "R65", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "Вы говорите: соседка Шмидтов видела Фархада у того дома. В субботу вечером, в четверть седьмого.\nВалентина Петровна встаёт. Подходит к серванту. За стеклом конверт, на нём её карандашом: «От Фархада — на похороны».\n— Двадцать лет. Вот на этом стуле. По пятницам плов. Игорь у него мальчишкой начинал… — Замолкает. — В воскресенье он пришёл. Вечером. Принёс вот это. А рука у него была расцарапана. Свежо так, красно. Я спросила. Собака, говорит, на базаре. — Пауза. — А уже в пальто, в прихожей, взял меня за локоть. Тихо так: «Бандиты сейчас такие, Валентина-апа. Береги Дашу. Никому ни слова». И я подумала: ну хоть один… хоть один обо мне думает. — Закрывает дверцу серванта. — Больше не спрашивайте. Я не знаю, что это значит. Не знаю.", "grants": ["e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c"], "group": "group-2", "repeat_text": "«Я вам уже всё рассказала. Больше мне добавить нечего»."}, {"id": "R66", "on": "27ae146a-a05c-5e7a-84a1-899c35e883e4", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "Вы говорите: пальцы Мамаджанова сняты с люка подвала. Того, где держали Игоря.\nВалентина Петровна выходит в прихожую. Встаёт у зеркала, оно ещё завешено простынёй.\n— Вот здесь он стоял. В воскресенье. Уже в пальто. — Голос ровный, руки сцеплены. — Принёс конверт на похороны. Рука расцарапана, свежая. Я спросила. Собака на базаре, сказал. А здесь, у двери… взял за локоть: «Бандиты сейчас такие, Валентина-апа. Береги Дашу. Никому ни слова». Двадцать лет он у меня за столом сидел. Я тогда подумала: бережёт. Бережёт он меня. — Поправляет простыню, хотя та висит ровно. — Идите. Мне надо одной побыть.", "grants": ["e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c"], "group": "group-2", "repeat_text": "«Я вам уже всё рассказала. Больше мне добавить нечего»."}, {"id": "R69", "on": "87af9a91-8540-5177-bdd6-3e156802fc75", "requires": [], "text": "Валентина Петровна берёт шарф двумя руками. Долго молчит.\n— Его. Я из Москвы привезла. Итальянский.\n(прижимает к лицу)\nСыростью пахнет. Где он лежал? Нет... Не говорите. Не надо.", "grants": []}, {"id": "R83", "on": "4f67be3f-f5f7-5ab5-bb69-611053df3042", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "— Даник снял копии? — Пауза. — Мне не сказал. Я бы рассердилась: зачем, лишь бы Игоря отпустили. А он, выходит, правильно сделал.", "grants": []}, {"id": "R84", "on": "552b22f9-f4c6-5469-8d1c-56bde54906aa", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "— Оттуда, значит, звонили. Из пустого дома.\n(закрывает глаза)\nА я сидела у аппарата и ждала. Думала, он где-то далеко. А он был в городе. Под землёй.", "grants": []}, {"id": "R109", "on": "7ada2011-2720-5b69-8a9c-9291fdad70e9", "requires": [], "text": "Валентина Петровна читает. На строке «от Сартаковой В. П.» останавливается.\n— Это я. Я ему всегда пишу: «Позвони маме». Он ругается: мама, люди смеются.\n(пауза)\n— Не перезвонил. — Голос ровный, учительский. — Он всегда перезванивал. Всегда.", "grants": [], "fallback": true}, {"id": "R110", "on": "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "requires": [], "text": "Валентина Петровна поправляет платок.\n— Данияр рассказал. — Пауза. — Он хороший мальчик. Он делал то, что я велела. Я запретила ему идти к вам. Я.\n(смотрит на дверь кухни. Там люди)\n— Если кого судить — меня. Не его.", "grants": [], "fallback": true}, {"id": "R111", "on": "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba", "requires": [], "text": "— Шмидт. — Валентина Петровна повторяет фамилию. — Я не знаю никакого Шмидта.\n(рука сама тянется к АОН и останавливается на полпути)\n— Горный Гигант… У меня там никого нет. Никого.", "grants": [], "fallback": true}, {"id": "R112", "on": "4e8b269e-8c91-5629-b60d-13930fa7e61e", "requires": [], "text": "— Зоя Михайловна всё видит. Это у неё профессиональное. — Тень улыбки. — Да. Данияр был у меня. В субботу.\n(пауза)\n— Мне было нехорошо. Он сидел со мной. Курил на лестнице, я не терплю дыма в доме.\n— Это всё, что я могу сказать.", "grants": [], "fallback": true}, {"id": "R113", "on": "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c", "requires": [], "text": "Валентина Петровна дочитывает. Кладёт лист на стол. Выравнивает по краю.\n— «Я тебя узнал». — Тихо. — Игорь узнал его. Через мешок. По кашлю.\n(долго молчит. Спина прямая)\n— Он у меня по пятницам плов ел. Вот на этом стуле. — Встаёт. — Простите. Я выйду. На минуту.", "grants": [], "fallback": true}, {"id": "R114", "on": "26a10711-a53c-5105-9ed4-190697869496", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "Валентина Петровна смотрит на сервант. На конверт за стеклом.\n— Это наши деньги. — Голос не слушается. — Наши. Я их собирала. По сто. Сорок тысяч…\n(пауза)\n— А он мне их вернул. Пятьсот. «На похороны». — Закрывает глаза. — А я его чаем поила. На кухне.", "grants": [], "fallback": true}, {"id": "R115", "on": "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "requires": [], "text": "Валентина Петровна читает стоя. До конца.\n— Задушил. Один. — Перечитывает строку. — «Решение принял, когда…»\n(пауза. Голос ломается)\n— Двадцать лет. Я его Даше… Даша его дядей Фархадом зовёт.\n— Уходите. Пожалуйста. Мне нужно побыть одной.", "grants": [], "fallback": true}, {"id": "R198", "on": "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "— Оттуда звонили. Из чужого дома. А я не знала, где это.", "grants": [], "supersedes": ["R111"], "fallback": true}, {"id": "R202", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": [], "text": "Валентина Петровна читает. Не садится.\n— Задушен… — Долго молчит. Спина прямая. — Я ничего не знаю. Он уехал в четверг. Я думала, по делам. — Возвращает лист. — Извините. У меня люди.", "grants": [], "fallback": true}, {"id": "R203", "on": "7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3", "requires": [], "text": "Валентина Петровна читает строчку про собаку. Дважды.\n— Не собака. — Кладёт лист. — А я ему йод предлагала.", "grants": [], "fallback": true}, {"id": "R232", "on": "26a10711-a53c-5105-9ed4-190697869496", "requires": [], "text": "Валентина Петровна смотрит на сервант.\n— Это… — Голос не слушается. — Это от Фархада. Он сказал: на похороны. — Долго молчит. — Я не знаю, что вам ответить. Не сейчас.", "grants": [], "fallback": true}, {"id": "R233", "on": "4e8b269e-8c91-5629-b60d-13930fa7e61e", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "— Зоя Михайловна всё видит. — Тень улыбки. — Да. Данияр был у меня. Мы ждали звонка. Я вам уже рассказала.", "grants": [], "supersedes": ["R112"], "fallback": true}, {"id": "R238", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": ["1ac01ab0-e8f1-5009-9640-d18dfa4f5e44", "b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "— Задушен. — Спина прямая. — Я вам всё рассказала. Найдите его. Вы уже нашли.", "grants": [], "supersedes": ["R09"]}, {"id": "R239", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": [], "text": "Валентина Петровна читает. Спина прямая.\n— «Грелся в машине». — Возвращает лист. — Игорь гаража боялся. Но я ничего не знаю. Извините, у меня люди.", "grants": [], "fallback": true}, {"id": "R240", "on": "0146fe89-1029-5d65-87bb-f750dfe7ad2d", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "Валентина Петровна дочитывает.\n— Это он звонил. Мальчишеский голос. — Пауза. — Двадцать два года.", "grants": [], "fallback": true}]'::jsonb, reactions = '{"e4e94374-000e-52e3-bb26-9bec42b1c55b": "Валентина Петровна смотрит на красные цифры АОН. Потом на свой блокнот.\n— Игорь поставил. Чтобы я знала, кто звонит. Ну вот. Знаю. — Садится, спинки стула не касается. — В четверг. Около девяти. Из автомата. Шестьдесят тысяч долларов. Пойдёте в милицию — Дашу не увидите. — Пауза. — Мы с Данияром собрали сорок. Больше не было. Не было больше.\nВ субботу, в половине четвёртого, ещё раз. Вот этот номер. Данияр рядом стоял, видел. Он отвёз деньги. Вернулся. И мы сидели. С половины восьмого до половины второго, здесь, у телефона. Ждали. — Нажимает кнопку, цифры гаснут. — Он так радовался этой коробочке. «Мама, теперь ты всё будешь знать».", "54bf13bc-3525-5eec-9441-609d8ee21f59": "Вы кладёте перед ней заключение Кана и пейджер из арыка. Говорите: если вам угрожают, молчание никого не защитит. Защитить может только милиция.\nНа кухне перестают звенеть посудой.\n— Я тридцать лет учила детей говорить правду. Тридцать лет. А сама… — Долгая пауза. — Хорошо. Хорошо. Четверг, около девяти. Автомат. Шестьдесят тысяч. И если в милицию — Дашу мы больше не увидим. — Сбивается. — Мы с Данияром собрали сорок. Виктору я сказала: Игорь в Бишкеке. Суббота… половина четвёртого. Второй звонок, номер в АОН остался. Данияр отвёз деньги. Вернулся. С половины восьмого до половины второго был со мной. Ждали. — Голос ломается. — Я молчала из-за Даши. Из-за Даши.", "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44": "Валентина Петровна берёт пейджер. Смотрит на АОН. На блокнот, где цифры её почерком.\n— Его пейджер. В арыке, у ворот… Он не уезжал в Бишкек. — Пауза. — Это я придумала. В пятницу утром позвонила Виктору: Игорь в Бишкеке, вы свободны. Он поверил. Он мне всегда верит. — Дальше коротко, как диктант диктует: — Четверг, девять вечера. Автомат. Шестьдесят тысяч, иначе внучка. С Данияром собрали сорок. Суббота, пятнадцать тридцать, вот этот номер. Данияр отвёз деньги, вернулся. С половины восьмого до половины второго был со мной. — Кладёт пейджер. — Скажите Виктору сами. Я не смогу… Я ему в глаза не смогу.", "f725c4c5-f254-5c01-b718-3531a957102a": "Вы говорите: соседка Шмидтов видела Фархада у того дома. В субботу вечером, в четверть седьмого.\nВалентина Петровна встаёт. Подходит к серванту. За стеклом конверт, на нём её карандашом: «От Фархада — на похороны».\n— Двадцать лет. Вот на этом стуле. По пятницам плов. Игорь у него мальчишкой начинал… — Замолкает. — В воскресенье он пришёл. Вечером. Принёс вот это. А рука у него была расцарапана. Свежо так, красно. Я спросила. Собака, говорит, на базаре. — Пауза. — А уже в пальто, в прихожей, взял меня за локоть. Тихо так: «Бандиты сейчас такие, Валентина-апа. Береги Дашу. Никому ни слова». И я подумала: ну хоть один… хоть один обо мне думает. — Закрывает дверцу серванта. — Больше не спрашивайте. Я не знаю, что это значит. Не знаю.", "27ae146a-a05c-5e7a-84a1-899c35e883e4": "Вы говорите: пальцы Мамаджанова сняты с люка подвала. Того, где держали Игоря.\nВалентина Петровна выходит в прихожую. Встаёт у зеркала, оно ещё завешено простынёй.\n— Вот здесь он стоял. В воскресенье. Уже в пальто. — Голос ровный, руки сцеплены. — Принёс конверт на похороны. Рука расцарапана, свежая. Я спросила. Собака на базаре, сказал. А здесь, у двери… взял за локоть: «Бандиты сейчас такие, Валентина-апа. Береги Дашу. Никому ни слова». Двадцать лет он у меня за столом сидел. Я тогда подумала: бережёт. Бережёт он меня. — Поправляет простыню, хотя та висит ровно. — Идите. Мне надо одной побыть.", "87af9a91-8540-5177-bdd6-3e156802fc75": "Валентина Петровна берёт шарф двумя руками. Долго молчит.\n— Его. Я из Москвы привезла. Итальянский.\n(прижимает к лицу)\nСыростью пахнет. Где он лежал? Нет... Не говорите. Не надо.", "4f67be3f-f5f7-5ab5-bb69-611053df3042": "— Даник снял копии? — Пауза. — Мне не сказал. Я бы рассердилась: зачем, лишь бы Игоря отпустили. А он, выходит, правильно сделал.", "552b22f9-f4c6-5469-8d1c-56bde54906aa": "— Оттуда, значит, звонили. Из пустого дома.\n(закрывает глаза)\nА я сидела у аппарата и ждала. Думала, он где-то далеко. А он был в городе. Под землёй."}'::jsonb where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';  -- Валентина Петровна Сартакова
update characters set reaction_rules = '[{"id": "R54", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": [], "text": "Зоя Михайловна всё это время стоит в дверях кухни. Полотенце через плечо. Откашливается.\n— Я не сплетничаю. Я констатирую. Если Валентина Петровна говорит, что Данияр в субботу был здесь, — значит, был. «Девятка» его белая под моим окном стояла. С вечера и до глубокой ночи. Он её вечно колесом на газон ставит, я ему сто раз… — Машет рукой. — А около десяти, перед вторым «Временем», опять потянуло табаком. Я вышла на площадку. Стоит, курит. Заграничные. И окурки в банку у мусоропровода. Я ему говорю: молодой человек, тут люди живут.", "grants": ["4e8b269e-8c91-5629-b60d-13930fa7e61e"]}, {"id": "R55", "on": "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "requires": [], "text": "— Данияр? Говорит, был здесь в субботу? — Зоя Михайловна поджимает губы. — Был. Я не сплетничаю, я констатирую. «Девятка» его белая под окном стояла. С вечера до глубокой ночи. Я её видела, когда шторы задёргивала. И ещё раз, когда телевизор выключала. — Пауза. — А около десяти, перед вторым «Временем», он на лестнице курил. Я вышла сказать: у нас тут не вокзал. Он извинился. Вежливый. Но курил.", "grants": ["4e8b269e-8c91-5629-b60d-13930fa7e61e"]}]'::jsonb, reactions = '{"b170d031-ba6c-5e70-829f-cbd96f761931": "Зоя Михайловна всё это время стоит в дверях кухни. Полотенце через плечо. Откашливается.\n— Я не сплетничаю. Я констатирую. Если Валентина Петровна говорит, что Данияр в субботу был здесь, — значит, был. «Девятка» его белая под моим окном стояла. С вечера и до глубокой ночи. Он её вечно колесом на газон ставит, я ему сто раз… — Машет рукой. — А около десяти, перед вторым «Временем», опять потянуло табаком. Я вышла на площадку. Стоит, курит. Заграничные. И окурки в банку у мусоропровода. Я ему говорю: молодой человек, тут люди живут.", "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e": "— Данияр? Говорит, был здесь в субботу? — Зоя Михайловна поджимает губы. — Был. Я не сплетничаю, я констатирую. «Девятка» его белая под окном стояла. С вечера до глубокой ночи. Я её видела, когда шторы задёргивала. И ещё раз, когда телевизор выключала. — Пауза. — А около десяти, перед вторым «Временем», он на лестнице курил. Я вышла сказать: у нас тут не вокзал. Он извинился. Вежливый. Но курил."}'::jsonb where id = '753087d6-7c38-5bf7-889e-3c4477902369';  -- Зоя Михайловна Лукина
update characters set reaction_rules = '[{"id": "R07", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": [], "text": "Фархад берёт протокол двумя руками. Левая кисть в бинте.\nЧитает долго, шевелит губами.\n— Угорел… Грелся, значит. Эх, Игорь, Игорь. — Поднимает глаза. — Мы с ним давно помирились, дорогой, ты не думай. Зла не держал. Дай бог каждому такого друга. — Замечает, куда вы смотрите. Приподнимает руку. — Это? Казан. Плов делал, обжёгся, как мальчишка. Заживёт. — Пауза. — А у нас в «Орбите» в субботу тоже свет отключили. Сидел один при свечке. Чай пил. Зарина моя у родни в Ташкенте, с четверга. Думал, Игорь позвонит, а он… — Разглаживает протокол ладонью. — Пойду к Валентине-апа. Ей сейчас одной нельзя.", "grants": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "abc6fac8-abbd-5589-b6b5-958cd368e7fe"]}, {"id": "R31", "on": "009a36f7-b362-586d-8943-61cd46149c3c", "requires": ["4cc34317-760f-577c-b05f-e0374aee4f23", "cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "Перед Фархадом запись КПП за двадцать восьмое октября и показания Ахметова.\nОн долго молчит. Потом тихо, уже без «дорогой»:\n— Помирились… Нет. Не помирились. Я за него сидел. Полтора года. Ты знаешь, что такое полтора года, когда тебе сорок семь? — Пауза. — Он обещал: доля твоя, семья твоя под присмотром. Я вышел. А базы моей нет. Есть их АО. Я к нему пришёл по-человечески. А он мне — «завскладом». При своём счетоводе, при нём. — Кашляет. — Да. Обиделся. Только обиду в милицию не носят, слушай. Обида — не преступление.", "grants": []}, {"id": "R32", "on": "64b699fc-69d6-5bc3-ab81-b5a48df561bd", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a", "cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "Фархад на справку не смотрит. Смотрит на вас.\n— Был свет? — Пожимает плечами. — Ну, значит, перепутал. Не в субботу отключали. В пятницу.\nВы кладёте рядом показания соседки Шмидтов: белая «Волга», одна фара, четверть седьмого. Он кашляет до слёз, вытирает глаза ладонью.\n— Ну заезжал. Да. Чего ты так смотришь? Дом показывал покупателю. Дом по доверенности на мне, я право имею. Посидели с лампой, света ж там не было. Он уехал, я тоже. — Пауза. — А со свечкой перепутал, говорю тебе. У нас в пятницу отключали. В пятницу. — Голос уже не отеческий. — Всё. Устал я, слушай.", "grants": ["7188cb7d-2261-5a9c-8f78-e603caa6b31a"], "group": "group-3", "repeat_text": "«Я уже всё сказал. Больше добавить нечего»."}, {"id": "R33", "on": "7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3", "requires": [], "text": "Фархад смотрит на свою кисть. Голая, без бинта.\n— Ногти… Собака это. На базаре. — И сам себя поправляет: — Казан. Обжёгся я. — Пауза. Кан при понятых сказал: ожога нет. Он это слышал. — Казан, собака… Какая разница, дорогой? Вторая группа у половины базара. Ты меня за группу крови посадишь? — Отворачивается к окну. Молчит долго. Потом не вам: — Зарина… Дочка у меня. Семнадцать лет. — И замолкает.\nНа этот допрос его больше не хватает.", "grants": []}, {"id": "R34", "on": "27ae146a-a05c-5e7a-84a1-899c35e883e4", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a", "cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "— Пальцы на лампе? — Фархад усмехается углом рта. — Мои, конечно. Я этот дом продаю. Лампы трогал, двери трогал. Всё трогал.\nВы напоминаете про люк в подвал. И про соседку: «Волга» у калитки, суббота, вечер. Он молчит. Долго.\n— Ну. Заезжал. В субботу. Покупателю дом показывал. Посидели с лампой, света ж не было. Он уехал, я тоже. — Пауза. — А про свечку дома перепутал. У нас в пятницу отключали. — Смотрит прямо. — Ты молодой ещё, дорогой. Не ищи там, где не надо.", "grants": ["7188cb7d-2261-5a9c-8f78-e603caa6b31a"], "group": "group-3", "repeat_text": "«Я уже всё сказал. Больше добавить нечего»."}, {"id": "R35", "on": "26a10711-a53c-5105-9ed4-190697869496", "requires": ["cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "Фархад смотрит на протокол сравнения купюр. Лицо у него каменеет.\n— Это от сердца было. — Пауза. Совсем тихо: — Валентине-апа не говори. Как человека прошу. Двадцать лет я за её столом… Пусть думает, что от сердца. Пусть думает. — Прячет руки в рукава. Смотрит мимо вас, на дверь. — Больше ничего не скажу. Делай свою работу, дорогой.", "grants": []}, {"id": "R37", "on": "5cdb3307-fe10-53c5-a365-6998256b7d7a", "requires": [], "text": "Фархад отмахивается перевязанной рукой.\n— Конверт? Я принёс, да. Свои. От сердца. Похороны сейчас сам знаешь сколько… а Валентина-апа одна. — Видит, что вы смотрите на бинт. — Это? Казан. Обжёгся. Не обращай внимания, дорогой. — Пауза. — Мы с Игорем давно помирились. Что было, то было. Зла не держу. В субботу у себя в «Орбите» сидел. Один, Зарина у родни в Ташкенте. Свет отключили, при свечке сидел. Кто ж знал, что он в ту ночь… — Не договаривает. — Ты её сегодня не мучай, дорогой. Она держится. Но это снаружи.", "grants": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "abc6fac8-abbd-5589-b6b5-958cd368e7fe"]}, {"id": "R36", "on": "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c", "requires": ["6fc41a46-a0eb-5890-9b26-3b19bcef490d", "7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3", "cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "Олжаса уводят. Фархад смотрит на закрытую дверь. Потом говорит медленно, по-отечески. В последний раз.\n— Мальчика пожалей. Он не знал. Я ему сказал: никто не пострадает. Я и сам тогда верил. — Пауза. — Слушай сюда. Ерлану я долг списал. За четверги. Больше он ничего не знал. Игоря мы взяли. Я долю хотел. Свою. Только долю, понимаешь? — Кашляет. — А потом Олжас приходит: он тебя узнал. И я понял. Живой — он меня посадит. А Зарина одна останется. С моими долгами. Они к ней уже приходили, к дочке моей… — Долго молчит. — Я его сам. Один. Потом на Кок-Тобе отвёз, на его же машине. Мотор завёл. Вниз пешком. Внизу частника поймал, номера не помню, не спрашивай. Часть денег кредитору отдал. Остальное ты нашёл. — Поднимает глаза. — Пощады не прошу. Дочку только не трогайте.", "grants": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db"]}, {"id": "R63", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": ["7188cb7d-2261-5a9c-8f78-e603caa6b31a", "cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "Вы читаете Фархаду показания Шнайдер. Строчку за строчкой. Из «Волги» вышли двое: он и высокий парень. Парень скоро ушёл пешком. Больше в тот вечер никто не приезжал. «Волга» стояла у калитки до половины второго ночи. Уехала по свежему снегу.\nФархад смотрит на свои руки.\n— Покупатель… — И не заканчивает. Долго кашляет. — Не спит старуха, значит. Всё видит. — Пауза. — Сейчас спросишь, как его зовут. Не спрашивай, дорогой. Нету его.\nБольше на этот допрос он ничего не говорит.", "grants": []}, {"id": "R71", "on": "abc6fac8-abbd-5589-b6b5-958cd368e7fe", "requires": [], "text": "— Казан. Плов делал, обжёгся. Заживёт.\nВы не за этим пришли, товарищ следователь.", "grants": []}, {"id": "R72", "on": "4cc34317-760f-577c-b05f-e0374aee4f23", "requires": [], "text": "— Ну, был на базе. В октябре. К Игорю зашёл, по старой памяти.\n(пожимает плечами)\nПоговорили и разошлись. Что тут записывать? Охрана у них от скуки всех пишет.", "grants": []}, {"id": "R73", "on": "00b31a8e-e1ee-5474-a323-177b43b153d3", "requires": [], "text": "— Обыск, значит, сделали. Ну, мои ботинки. Зимние. Сорок третий.\n(долго смотрит на каблук)\nПорез? Где-то зацепил. Мало ли где человек ходит, товарищ следователь.", "grants": []}, {"id": "R74", "on": "2d1a03f4-be7f-5007-8fe1-71c12d498c29", "requires": [], "text": "— Это мои сбережения. Всю жизнь копил.\nВ банк сейчас только дурак понесёт: сегодня банк есть, завтра нет.\n(отворачивается)\nА бумаги Шмидтов у меня по доверенности. Дом продаю, люди попросили.", "grants": []}, {"id": "R75", "on": "b322dfba-0cb0-52bc-9610-328a905bc004", "requires": [], "text": "— Долги отдавал. Людям. Летом товар пропал, из Урумчи, — занимал под проценты, теперь отдаю. Это что, запрещено?", "grants": []}, {"id": "R76", "on": "6a92b637-cb0c-5bf4-8495-f503839bf08c", "requires": [], "text": "— Олжас? Племянник. Сестры сын.\nИз аула приехал, на базаре грузит. Я ему помогаю, как могу. Мальчик хороший.\n(резко)\nЕго не трогайте. Он тут ни при чём.", "grants": []}, {"id": "R77", "on": "e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c", "requires": [], "text": "— Валентина-апа переживает. Ей сейчас всякое кажется.\nСобака это. На базаре, у мясных рядов. Я же ей говорил.\n(прячет руку)", "grants": []}, {"id": "R87", "on": "e34a96b0-5d0e-5414-9ef3-048071ef84ed", "requires": [], "text": "Фархад долго молчит.\n— Игорь... Двадцать лет его знал. Мальчишкой ко мне пришёл.\n(отворачивается)\nНе надо мне это показывать, товарищ следователь.", "grants": []}, {"id": "R88", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": [], "text": "— Подвал как подвал. Я дом продаю, по доверенности.\nВ подвал не лазил, что мне там делать.\nПокупателям кухню показывал, комнаты.", "grants": []}, {"id": "R89", "on": "87af9a91-8540-5177-bdd6-3e156802fc75", "requires": [], "text": "— Шарф...\n(не смотрит)\nМало ли у кого какие шарфы. Не знаю.", "grants": []}, {"id": "R91", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": [], "text": "Фархад читает. Губы шевелятся.\n— Задушили?.. — Опускается на стул. Левую руку убирает за спину. — Игоря. Задушили, значит. Не угорел.\n(долго молчит)\n— Звери, дорогой. Кто ж такое… Двадцать лет его знаю. Найди их. Слышишь? Найди.", "grants": [], "fallback": true}, {"id": "R92", "on": "c4c95f03-86b0-5820-b9f4-736453e2dbef", "requires": [], "text": "— «Волга»… — Улыбается, по-отечески. — Дорогой, белых «Волг» в Алма-Ате больше, чем ворон. И фара у каждой второй разбита, дороги у нас какие, сам видишь.\n(пауза)\n— На базу я в октябре заходил. Это все знают, я не прятался. А в четверг стоять, на ворота смотреть… Зачем мне? Я не мальчишка.", "grants": [], "fallback": true}, {"id": "R93", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": [], "text": "— Похитили?.. — Перечитывает. Медленно. — Шестьдесят тысяч. И внучке грозили.\n(трёт лицо ладонью)\n— И Валентина-апа молчала. Мне — ни слова. Двадцать лет за её столом, дорогой. Двадцать лет. — Пауза. — Боялась, значит. Правильно боялась. Сейчас время такое.", "grants": [], "fallback": true}, {"id": "R94", "on": "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "requires": [], "text": "— Выкуп… — Лицо не меняется. Только пальцы перестают мять шапку. — Данияр, значит, возил.\n(пауза)\n— И копии снял. Со всех. — Усмехается углом рта. — Счетовод. Он и на поминках салфетки пересчитает. — Кладёт лист на стол, разглаживает ладонью. — Хорошо, что снял. Пусть ищут теперь, кто взял. Пусть ищут.", "grants": [], "fallback": true}, {"id": "R95", "on": "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba", "requires": [], "text": "— Шмидта телефон? — Пауза. Длиннее, чем нужно. — Дом Шмидтов я продаю, да. По доверенности. Хорошие люди, уехали к своим.\n(отмахивается)\n— Телефон не отключили, видишь. Кто там ходит, кто смотрит, кто звонит — я за каждым не хожу, дорогой. Покупателей много. Спроси у них.", "grants": [], "fallback": true}, {"id": "R96", "on": "c50332f2-fb14-5cff-9ea2-9581024ac2e3", "requires": [], "text": "Фархад читает выписку. Возвращает. Двумя руками, вежливо.\n— «Ф.». Одна буква, дорогой. Фёдор, Фарида, Фарид. Полгорода на «Ф».\n(пауза)\n— Что за четверг, что в силе — спроси того, кому писали. По одной букве людей не сажают. Не при Сталине живём.", "grants": [], "fallback": true}, {"id": "R97", "on": "b229ab87-5e5b-5f61-8a7b-18c17718e4cf", "requires": [], "text": "— Ерлан… — Качает головой. — Бывший милиционер. Им верить — себя не уважать.\n(пауза)\n— Долг простил, да. Было. У человека мать болела, какие с него деньги? Это грех, по-твоему?\n— А что он там про четверги говорит… Не помню я такого разговора, дорогой. Мало ли что в чайхане скажешь. Обида — она в милицию не ходит.", "grants": [], "fallback": true}, {"id": "R98", "on": "d91852b9-daca-5340-80c9-a13cffe680cc", "requires": [], "text": "— Бекенов… Олжас? — Впервые не находит слов. — Мальчик мешки таскает. Двадцать два года.\n(голос садится)\n— Где он деньги взял — не знаю, дорогой. Не знаю. Может, нашёл, может, дали. Он из аула, он не понимает ничего.\n— Его не трогай. Слышишь? Он ребёнок ещё.", "grants": [], "fallback": true}, {"id": "R99", "on": "0146fe89-1029-5d65-87bb-f750dfe7ad2d", "requires": [], "text": "Фархад дочитывает до конца. До строчки «действовал один».\n— Сам, значит. Сам сказал. Видишь? — Тихо. Не вам. — Дурак. Ой, дурак мальчишка…\n(долго молчит)\n— Это я виноват. Не досмотрел. При себе держал, работу давал — а не досмотрел. — Поднимает глаза. — Он тебе всё сказал, дорогой. Что ещё от меня хочешь?", "grants": [], "fallback": true}, {"id": "R100", "on": "6fc41a46-a0eb-5890-9b26-3b19bcef490d", "requires": ["cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "Кабинет. Фархад смотрит на свои ботинки в целлофане. Долго.\n— Мои. Сорок третий. Порез — гвоздём, на базаре зацепил.\n(кашляет, глухо)\n— На даче у Игоря я сто раз был, дорогой. Двадцать лет. — Пауза. — Когда был — не помню. Ты бы помнил, когда в гостях был?", "grants": [], "fallback": true}, {"id": "R101", "on": "107fcb2c-e909-5f81-bba4-d218265227c5", "requires": ["cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "Кабинет. На столе вспоротый мешок с рисом. Фархад на него не смотрит.\n— Мои деньги. В доме у меня — значит, мои.\n(кашляет)\n— Номера… Я номера не переписываю, дорогой. Я не Данияр. — Пауза. — Откуда пришли — с базара пришли. Деньги по рукам ходят. Сегодня у тебя, завтра у меня.\n— Больше по деньгам ничего не скажу.", "grants": [], "fallback": true}, {"id": "R175", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "Фархад отодвигает протокол.\n— Угорел… Это я так хотел, чтоб написали. Написали. — Кашляет. — Я всё сказал, дорогой. Подписал. Больше по этой бумаге нечего.", "grants": [], "supersedes": ["R07", "R218"]}, {"id": "R176", "on": "5cdb3307-fe10-53c5-a365-6998256b7d7a", "requires": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db"], "text": "— Пятьсот. Из тех денег, да. — Долго молчит. — Хотел, чтоб ей на похороны хватило. Глупость сделал, дорогой. Ей не показывай.", "grants": [], "supersedes": ["R37", "R219"]}, {"id": "R177", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db"], "text": "Фархад на лист не смотрит.\n— Знаю, что там написано. Я ж сам. — Пауза. — Не читай мне это, дорогой. Не надо.", "grants": [], "supersedes": ["R91", "R222"], "fallback": true}, {"id": "R178", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db"], "text": "— Шестьдесят просили. Сорок дали. — Трёт лицо ладонью. — Даше никто бы ничего не сделал. Я её пугал, чтоб молчала. Валентине-апа скажи.", "grants": [], "supersedes": ["R93"], "fallback": true}, {"id": "R179", "on": "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "requires": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db"], "text": "— Копии снял, счетовод. — Усмехается углом рта. — На копиях я и сгорел. Его правда.", "grants": [], "supersedes": ["R94"], "fallback": true}, {"id": "R180", "on": "b229ab87-5e5b-5f61-8a7b-18c17718e4cf", "requires": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db"], "text": "— Ерлан правду говорит. Долг списал за четверги. — Пауза. — Он думал, разговор будет. Он больше ничего не знал, дорогой. Это я тебе уже сказал.", "grants": [], "supersedes": ["R97"], "fallback": true}, {"id": "R181", "on": "d91852b9-daca-5340-80c9-a13cffe680cc", "requires": ["3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c"], "text": "— Три тысячи. Я ему отсчитал. — Голос садится. — Мальчик не знал, за что. Его пожалей, дорогой.", "grants": [], "supersedes": ["R98"], "fallback": true}, {"id": "R182", "on": "e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c", "requires": ["7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3"], "text": "Фархад прячет руку в рукав.\n— Собака, казан… — Машет рукой. — Кан при понятых всё сказал. Что Валентина-апа видела, то и было.", "grants": [], "supersedes": ["R77"]}, {"id": "R183", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": ["27ae146a-a05c-5e7a-84a1-899c35e883e4"], "text": "— Подвал… — Долго молчит. — Пальцы мои там, ты знаешь. Чего спрашиваешь, дорогой.", "grants": [], "supersedes": ["R88"]}, {"id": "R184", "on": "2d1a03f4-be7f-5007-8fe1-71c12d498c29", "requires": ["107fcb2c-e909-5f81-bba4-d218265227c5"], "text": "— Нашли, значит. — Отворачивается. — Что кредитору не отдал, то тут. Бумаги Шмидтов — по доверенности, они ни при чём.", "grants": [], "supersedes": ["R74"]}, {"id": "R185", "on": "107fcb2c-e909-5f81-bba4-d218265227c5", "requires": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "Фархад на мешок не смотрит.\n— Это остаток. Я тебе сказал. — Кашляет. — Больше по деньгам ничего не скажу.", "grants": [], "supersedes": ["R101"], "fallback": true}, {"id": "R186", "on": "6fc41a46-a0eb-5890-9b26-3b19bcef490d", "requires": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "— Мои. Сорок третий. — Кашляет, глухо. — Я там был в ту ночь. Сказал уже.", "grants": [], "supersedes": ["R100"], "fallback": true}, {"id": "R187", "on": "27ae146a-a05c-5e7a-84a1-899c35e883e4", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a", "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "— Мои пальцы. Я там был. Всё в протоколе, дорогой.", "grants": [], "supersedes": ["R34", "R237"]}, {"id": "R188", "on": "64b699fc-69d6-5bc3-ab81-b5a48df561bd", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a", "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "— Не отключали. Знаю. Наврал я про свечку. — Отодвигает справку.", "grants": [], "supersedes": ["R32"]}, {"id": "R189", "on": "c50332f2-fb14-5cff-9ea2-9581024ac2e3", "requires": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db"], "text": "— «Ф.» — это я. Ерлану писал. Сказал уже, дорогой.", "grants": [], "supersedes": ["R96"], "fallback": true}, {"id": "R190", "on": "4cc34317-760f-577c-b05f-e0374aee4f23", "requires": ["009a36f7-b362-586d-8943-61cd46149c3c"], "text": "— Двадцать восьмое. Был. Остальное ты от Данияра слышал.", "grants": [], "supersedes": ["R72"]}, {"id": "R199", "on": "cefb9e58-2cc4-5054-a43b-6216c7645217", "requires": [], "text": "Фархад читает. Кладёт лист на стол двумя руками.\n— Санкционирую… Ну, раз прокурор подписал. — Встаёт. — Пальто дай надеть, дорогой. И Зарине сообщите. Она в Ташкенте.", "grants": [], "fallback": true}, {"id": "R200", "on": "b177dd97-7391-5f5e-8308-72a1073516c2", "requires": [], "text": "Фархад смотрит на первую строчку.\n— Вторая. Ну. — Усмехается углом рта. — У половины базара вторая, дорогой. Ахметов, вон, тоже вторая. Его спроси.", "grants": [], "fallback": true}, {"id": "R201", "on": "d8f33493-fc81-5e50-af40-37d9500040b6", "requires": [], "text": "— «Волга» моя, белая. Ну и что? Двадцать лет езжу. Это не секрет, дорогой.", "grants": [], "fallback": true}, {"id": "R215", "on": "7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3", "requires": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db"], "text": "Фархад смотрит на голую кисть.\n— Игорь. Ногтями. — Пауза. — Не собака и не казан. Это я тебе уже сказал.", "grants": [], "supersedes": ["R33"]}, {"id": "R216", "on": "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba", "requires": ["7188cb7d-2261-5a9c-8f78-e603caa6b31a"], "text": "— Телефон Шмидтов. — Пауза. — Звонить оттуда я никому не звонил, дорогой. Кто звонил — у того и спрашивай.", "grants": [], "supersedes": ["R95"], "fallback": true}, {"id": "R217", "on": "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba", "requires": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "7188cb7d-2261-5a9c-8f78-e603caa6b31a"], "text": "— Олжас оттуда звонил. Я не знал. — Пауза. — Знал бы — не дал. Дурак мальчишка.", "grants": [], "supersedes": ["R216", "R95"], "fallback": true}, {"id": "R218", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": ["cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "Фархад на протокол не смотрит.\n— Угорел, написали. — Пауза. — Я тебе про субботу уже сказал, дорогой. Больше по этой бумаге нечего.", "grants": [], "supersedes": ["R07"]}, {"id": "R219", "on": "5cdb3307-fe10-53c5-a365-6998256b7d7a", "requires": ["cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "— Конверт мой. На похороны. — Прячет руки в рукава. — Свои дал. От сердца. Больше ничего не скажу.", "grants": [], "supersedes": ["R37"]}, {"id": "R220", "on": "abc6fac8-abbd-5589-b6b5-958cd368e7fe", "requires": ["7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3"], "text": "— Кан смотрел. Что он написал — то и есть.\n(прячет кисть в рукав)", "grants": [], "supersedes": ["R71"]}, {"id": "R221", "on": "abc6fac8-abbd-5589-b6b5-958cd368e7fe", "requires": ["7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3", "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db"], "text": "— Игорь. Ногтями. Сказал уже.", "grants": [], "supersedes": ["R220", "R71"]}, {"id": "R222", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": ["cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "Фархад читает. Левую руку убирает под стол.\n— Задушили. — Долго молчит. — Двадцать лет я его знал. Что ты от меня хочешь услышать, дорогой?", "grants": [], "supersedes": ["R91"], "fallback": true}, {"id": "R223", "on": "26a10711-a53c-5105-9ed4-190697869496", "requires": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "— Из тех денег. Знаю. — Пауза. — Валентине-апа не говори, как человека прошу. Хоть это.", "grants": [], "supersedes": ["R35"]}, {"id": "R224", "on": "87af9a91-8540-5177-bdd6-3e156802fc75", "requires": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db"], "text": "Фархад на шарф не смотрит.\n— Его. Олжас ему дал, под голову. — Пауза. — Убери, дорогой.", "grants": [], "supersedes": ["R89"]}, {"id": "R225", "on": "00b31a8e-e1ee-5474-a323-177b43b153d3", "requires": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db"], "text": "— Мои. В них и был там, у гаража. Мыл — не отмыл. — Пауза. — Сказал уже.", "grants": [], "supersedes": ["R73"]}, {"id": "R226", "on": "0146fe89-1029-5d65-87bb-f750dfe7ad2d", "requires": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db"], "text": "— «Сам придумал»… Дурак. Меня выгораживал. — Тихо. — Я его позвал. Я ему сказал: никто не пострадает.", "grants": [], "supersedes": ["R99"], "fallback": true}, {"id": "R227", "on": "b177dd97-7391-5f5e-8308-72a1073516c2", "requires": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db"], "text": "— Вторая. Моя. — Пауза. — Ахметова не трогай, дорогой. Он тут ни при чём.", "grants": [], "supersedes": ["R200"], "fallback": true}, {"id": "R228", "on": "6a92b637-cb0c-5bf4-8495-f503839bf08c", "requires": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db"], "text": "— Олжас. Сестры сын. — Голос садится. — Я его втянул. Он не знал, на что идёт. Пожалей мальчика.", "grants": [], "supersedes": ["R76"]}, {"id": "R237", "on": "27ae146a-a05c-5e7a-84a1-899c35e883e4", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a", "cefb9e58-2cc4-5054-a43b-6216c7645217", "7188cb7d-2261-5a9c-8f78-e603caa6b31a"], "text": "— Мои пальцы. Я ж говорил: покупателю дом показывал. — Отворачивается.", "grants": [], "supersedes": ["R34"]}]'::jsonb, reactions = '{"43eaf70c-177d-516a-9ab2-7aecc9633e33": "Фархад берёт протокол двумя руками. Левая кисть в бинте.\nЧитает долго, шевелит губами.\n— Угорел… Грелся, значит. Эх, Игорь, Игорь. — Поднимает глаза. — Мы с ним давно помирились, дорогой, ты не думай. Зла не держал. Дай бог каждому такого друга. — Замечает, куда вы смотрите. Приподнимает руку. — Это? Казан. Плов делал, обжёгся, как мальчишка. Заживёт. — Пауза. — А у нас в «Орбите» в субботу тоже свет отключили. Сидел один при свечке. Чай пил. Зарина моя у родни в Ташкенте, с четверга. Думал, Игорь позвонит, а он… — Разглаживает протокол ладонью. — Пойду к Валентине-апа. Ей сейчас одной нельзя.", "009a36f7-b362-586d-8943-61cd46149c3c": "Перед Фархадом запись КПП за двадцать восьмое октября и показания Ахметова.\nОн долго молчит. Потом тихо, уже без «дорогой»:\n— Помирились… Нет. Не помирились. Я за него сидел. Полтора года. Ты знаешь, что такое полтора года, когда тебе сорок семь? — Пауза. — Он обещал: доля твоя, семья твоя под присмотром. Я вышел. А базы моей нет. Есть их АО. Я к нему пришёл по-человечески. А он мне — «завскладом». При своём счетоводе, при нём. — Кашляет. — Да. Обиделся. Только обиду в милицию не носят, слушай. Обида — не преступление.", "64b699fc-69d6-5bc3-ab81-b5a48df561bd": "Фархад на справку не смотрит. Смотрит на вас.\n— Был свет? — Пожимает плечами. — Ну, значит, перепутал. Не в субботу отключали. В пятницу.\nВы кладёте рядом показания соседки Шмидтов: белая «Волга», одна фара, четверть седьмого. Он кашляет до слёз, вытирает глаза ладонью.\n— Ну заезжал. Да. Чего ты так смотришь? Дом показывал покупателю. Дом по доверенности на мне, я право имею. Посидели с лампой, света ж там не было. Он уехал, я тоже. — Пауза. — А со свечкой перепутал, говорю тебе. У нас в пятницу отключали. В пятницу. — Голос уже не отеческий. — Всё. Устал я, слушай.", "7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3": "Фархад смотрит на свою кисть. Голая, без бинта.\n— Ногти… Собака это. На базаре. — И сам себя поправляет: — Казан. Обжёгся я. — Пауза. Кан при понятых сказал: ожога нет. Он это слышал. — Казан, собака… Какая разница, дорогой? Вторая группа у половины базара. Ты меня за группу крови посадишь? — Отворачивается к окну. Молчит долго. Потом не вам: — Зарина… Дочка у меня. Семнадцать лет. — И замолкает.\nНа этот допрос его больше не хватает.", "27ae146a-a05c-5e7a-84a1-899c35e883e4": "— Пальцы на лампе? — Фархад усмехается углом рта. — Мои, конечно. Я этот дом продаю. Лампы трогал, двери трогал. Всё трогал.\nВы напоминаете про люк в подвал. И про соседку: «Волга» у калитки, суббота, вечер. Он молчит. Долго.\n— Ну. Заезжал. В субботу. Покупателю дом показывал. Посидели с лампой, света ж не было. Он уехал, я тоже. — Пауза. — А про свечку дома перепутал. У нас в пятницу отключали. — Смотрит прямо. — Ты молодой ещё, дорогой. Не ищи там, где не надо.", "26a10711-a53c-5105-9ed4-190697869496": "Фархад смотрит на протокол сравнения купюр. Лицо у него каменеет.\n— Это от сердца было. — Пауза. Совсем тихо: — Валентине-апа не говори. Как человека прошу. Двадцать лет я за её столом… Пусть думает, что от сердца. Пусть думает. — Прячет руки в рукава. Смотрит мимо вас, на дверь. — Больше ничего не скажу. Делай свою работу, дорогой.", "5cdb3307-fe10-53c5-a365-6998256b7d7a": "Фархад отмахивается перевязанной рукой.\n— Конверт? Я принёс, да. Свои. От сердца. Похороны сейчас сам знаешь сколько… а Валентина-апа одна. — Видит, что вы смотрите на бинт. — Это? Казан. Обжёгся. Не обращай внимания, дорогой. — Пауза. — Мы с Игорем давно помирились. Что было, то было. Зла не держу. В субботу у себя в «Орбите» сидел. Один, Зарина у родни в Ташкенте. Свет отключили, при свечке сидел. Кто ж знал, что он в ту ночь… — Не договаривает. — Ты её сегодня не мучай, дорогой. Она держится. Но это снаружи.", "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c": "Олжаса уводят. Фархад смотрит на закрытую дверь. Потом говорит медленно, по-отечески. В последний раз.\n— Мальчика пожалей. Он не знал. Я ему сказал: никто не пострадает. Я и сам тогда верил. — Пауза. — Слушай сюда. Ерлану я долг списал. За четверги. Больше он ничего не знал. Игоря мы взяли. Я долю хотел. Свою. Только долю, понимаешь? — Кашляет. — А потом Олжас приходит: он тебя узнал. И я понял. Живой — он меня посадит. А Зарина одна останется. С моими долгами. Они к ней уже приходили, к дочке моей… — Долго молчит. — Я его сам. Один. Потом на Кок-Тобе отвёз, на его же машине. Мотор завёл. Вниз пешком. Внизу частника поймал, номера не помню, не спрашивай. Часть денег кредитору отдал. Остальное ты нашёл. — Поднимает глаза. — Пощады не прошу. Дочку только не трогайте.", "f725c4c5-f254-5c01-b718-3531a957102a": "Вы читаете Фархаду показания Шнайдер. Строчку за строчкой. Из «Волги» вышли двое: он и высокий парень. Парень скоро ушёл пешком. Больше в тот вечер никто не приезжал. «Волга» стояла у калитки до половины второго ночи. Уехала по свежему снегу.\nФархад смотрит на свои руки.\n— Покупатель… — И не заканчивает. Долго кашляет. — Не спит старуха, значит. Всё видит. — Пауза. — Сейчас спросишь, как его зовут. Не спрашивай, дорогой. Нету его.\nБольше на этот допрос он ничего не говорит.", "abc6fac8-abbd-5589-b6b5-958cd368e7fe": "— Казан. Плов делал, обжёгся. Заживёт.\nВы не за этим пришли, товарищ следователь.", "4cc34317-760f-577c-b05f-e0374aee4f23": "— Ну, был на базе. В октябре. К Игорю зашёл, по старой памяти.\n(пожимает плечами)\nПоговорили и разошлись. Что тут записывать? Охрана у них от скуки всех пишет.", "00b31a8e-e1ee-5474-a323-177b43b153d3": "— Обыск, значит, сделали. Ну, мои ботинки. Зимние. Сорок третий.\n(долго смотрит на каблук)\nПорез? Где-то зацепил. Мало ли где человек ходит, товарищ следователь.", "2d1a03f4-be7f-5007-8fe1-71c12d498c29": "— Это мои сбережения. Всю жизнь копил.\nВ банк сейчас только дурак понесёт: сегодня банк есть, завтра нет.\n(отворачивается)\nА бумаги Шмидтов у меня по доверенности. Дом продаю, люди попросили.", "b322dfba-0cb0-52bc-9610-328a905bc004": "— Долги отдавал. Людям. Летом товар пропал, из Урумчи, — занимал под проценты, теперь отдаю. Это что, запрещено?", "6a92b637-cb0c-5bf4-8495-f503839bf08c": "— Олжас? Племянник. Сестры сын.\nИз аула приехал, на базаре грузит. Я ему помогаю, как могу. Мальчик хороший.\n(резко)\nЕго не трогайте. Он тут ни при чём.", "e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c": "— Валентина-апа переживает. Ей сейчас всякое кажется.\nСобака это. На базаре, у мясных рядов. Я же ей говорил.\n(прячет руку)", "e34a96b0-5d0e-5414-9ef3-048071ef84ed": "Фархад долго молчит.\n— Игорь... Двадцать лет его знал. Мальчишкой ко мне пришёл.\n(отворачивается)\nНе надо мне это показывать, товарищ следователь.", "c2c5ba62-e24e-523f-93bc-d8909b28e717": "— Подвал как подвал. Я дом продаю, по доверенности.\nВ подвал не лазил, что мне там делать.\nПокупателям кухню показывал, комнаты.", "87af9a91-8540-5177-bdd6-3e156802fc75": "— Шарф...\n(не смотрит)\nМало ли у кого какие шарфы. Не знаю."}'::jsonb where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8';  -- Фархад Мамаджанов
update characters set reaction_rules = '[{"id": "R14", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": [], "text": "Данияр снимает очки. Кладёт на стол дужками вверх. Ровно.\n— Валентина Петровна сказала... Значит, всё.\nДа. Знал. С пятницы. Она запретила идти в милицию. Я согласился.\nСорок тысяч взял из кассы, которой официально нет. И вернул туда то, что раньше вывел.\nВ субботу в пятнадцать тридцать был у неё. Когда позвонили. Номер на АОН сам видел. Переписал себе, цифра в цифру.\nОттуда с пакетом на Ташкентскую, на остановку. В семнадцать тридцать оставил под скамейкой.\nТемно уже. Парень... высокий, молодой. Спортивная куртка, ушанка. Лица не видел.\nПотом на базу. Въехал в семнадцать пятьдесят пять, выехал в девятнадцать десять. На КПП записано.\nВ девятнадцать тридцать вернулся к ней. До часу тридцати.\n(открывает нижний ящик) Копии всех купюр. Я не верил ни им, ни вам.", "grants": ["ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "4f67be3f-f5f7-5ab5-bb69-611053df3042"]}, {"id": "R15", "on": "e4e94374-000e-52e3-bb26-9bec42b1c55b", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"], "text": "Данияр смотрит на страницу блокнота. На лице что-то вроде облегчения.\n— Почерк Валентины Петровны. «Шестьдесят» — это тысяч. «Семнадцать тридцать, Ташкентская».\nВы уже всё поняли. (снимает очки)\nДа. С пятницы знал. В милицию не пошёл — она просила.\nСорок тысяч взял из «чёрной» кассы. Вернул туда то, что выводил.\nЭтот номер на АОН, в пятнадцать тридцать... я своими глазами видел. Я там был, когда звонили.\nВ семнадцать тридцать оставил пакет на остановке. Темно. Высокий, молодой. Спортивная куртка, ушанка. Лица — нет.\nПотом база. С семнадцати пятидесяти пяти до девятнадцати десяти, журнал КПП подтвердит.\nС половины восьмого до половины второго — опять у неё.\n(выдвигает ящик) Копии купюр. Все. Возьмите.", "grants": ["ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "4f67be3f-f5f7-5ab5-bb69-611053df3042"]}, {"id": "R16", "on": "4cc34317-760f-577c-b05f-e0374aee4f23", "requires": [], "text": "Данияр долго смотрит на строчку в журнале.\n— Двадцать восьмое октября. Шестнадцать десять. Да.\nЯ был в кабинете. Фархад пришёл просить свою долю. Спокойно. Вежливо. В галстуке пришёл.\nВы знаете, что он сидел? В девяносто четвёртом. За товар их с Игорем фирмы — взял на себя. Полтора года.\nИгорь ему тогда обещал всё сохранить.\nА тут при мне: «Я тебя садиться не просил. Хочешь — иди завскладом».\nФархад ничего не ответил. Встал и ушёл. Молча.\n(пауза) Я тогда подумал: лучше бы кричал.", "grants": ["009a36f7-b362-586d-8943-61cd46149c3c"]}, {"id": "R43", "on": "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"], "text": "Данияр впервые повышает голос. И тут же снимает очки.\n— Помирились? Он так сказал?\nИгорь его выгнал. При мне. Двадцать восьмого октября, в кабинете.\nФархад пришёл свою долю просить. Вежливо. В галстуке.\nОн же в девяносто четвёртом сел за товар их с Игорем кооператива. Всё на себя взял. Полтора года.\nА Игорь ему: «Я тебя садиться не просил. Хочешь — иди завскладом».\nФархад ушёл. Молча.\n(кладёт очки дужками вверх) Если это «помирились»... я не знаю тогда, что такое ссора.", "grants": ["009a36f7-b362-586d-8943-61cd46149c3c"]}, {"id": "R78", "on": "0a295d5f-e115-5c89-a26a-5992761304a0", "requires": [], "text": "— Виктор, значит.\n(поправляет очки)\nБыл разговор. По деньгам. Партнёры иногда ругаются.\nК тому, что с Игорем случилось, это отношения не имеет.", "grants": []}, {"id": "R79", "on": "9281d556-d163-5537-a0e2-e4cd2e635ba5", "requires": [], "text": "— Значит, проверили. Хорошо.\n(выдыхает)\nЯ вам с самого начала говорил: я его не трогал. Деньги — да. Но не это.", "grants": []}, {"id": "R80", "on": "06da149b-c92c-54fa-a5f5-b78ff87dbc92", "requires": [], "text": "— Вот видите. Сходится.\n(поправляет ручку на столе)\nЯ виноват перед Игорем. Но не в этом.", "grants": []}, {"id": "R85", "on": "5cdb3307-fe10-53c5-a365-6998256b7d7a", "requires": [], "text": "— Фархад принёс. В воскресенье вечером, я там был. Он её по руке гладил. Пятьсот долларов у человека, который всем должен. Я тогда ещё подумал: откуда.", "grants": []}, {"id": "R119", "on": "4e8b269e-8c91-5629-b60d-13930fa7e61e", "requires": [], "text": "Данияр поправляет ручку на столе. Параллельно калькулятору.\n— Зоя Михайловна. Да. Она делала мне замечание. По поводу курения.\n(пауза)\n— Хорошо. Я был не дома. Я был у Валентины Петровны. По личному вопросу.\n— Какому — спросите у неё. Без её согласия я об этом говорить не буду.", "grants": [], "fallback": true}, {"id": "R120", "on": "b177dd97-7391-5f5e-8308-72a1073516c2", "requires": [], "text": "Данияр читает. Пальцем ведёт по строчкам. Останавливается на своей фамилии.\n— Вторая. Да. Вторая. — Слишком быстро. — Как у тридцати восьми процентов населения. Примерно.\n(пауза)\n— Руки смотрите. Пожалуйста. Обувь, машину. Что угодно. Я не прячу ничего.", "grants": [], "fallback": true}, {"id": "R196", "on": "4e8b269e-8c91-5629-b60d-13930fa7e61e", "requires": ["ea60506a-dfdb-5176-a63a-2fd3c47f8b6e"], "text": "— Зоя Михайловна. Да. Делала мне замечание. — Поправляет ручку параллельно калькулятору. — С половины восьмого до половины второго я был там. Я вам это уже говорил.", "grants": [], "supersedes": ["R119"], "fallback": true}, {"id": "R207", "on": "7a9bdd9a-4323-5342-a3bd-24301a6d6e88", "requires": [], "text": "— Всё, что было, отдал. Сорок третий, да. Пореза нет. — Выдыхает. — Я же говорил: проверяйте.", "grants": [], "fallback": true}, {"id": "R241", "on": "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "requires": [], "text": "— Помирились? — Данияр поправляет очки. — Это вы у него спросите. Я своё скажу, когда будет повод.", "grants": [], "fallback": true}, {"id": "R242", "on": "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba", "requires": ["ea60506a-dfdb-5176-a63a-2fd3c47f8b6e"], "text": "— Тот самый номер. Цифра в цифру. — Снимает очки. — Пустой дом. Мы ждали у телефона, а он в городе был.", "grants": [], "fallback": true}]'::jsonb, reactions = '{"b170d031-ba6c-5e70-829f-cbd96f761931": "Данияр снимает очки. Кладёт на стол дужками вверх. Ровно.\n— Валентина Петровна сказала... Значит, всё.\nДа. Знал. С пятницы. Она запретила идти в милицию. Я согласился.\nСорок тысяч взял из кассы, которой официально нет. И вернул туда то, что раньше вывел.\nВ субботу в пятнадцать тридцать был у неё. Когда позвонили. Номер на АОН сам видел. Переписал себе, цифра в цифру.\nОттуда с пакетом на Ташкентскую, на остановку. В семнадцать тридцать оставил под скамейкой.\nТемно уже. Парень... высокий, молодой. Спортивная куртка, ушанка. Лица не видел.\nПотом на базу. Въехал в семнадцать пятьдесят пять, выехал в девятнадцать десять. На КПП записано.\nВ девятнадцать тридцать вернулся к ней. До часу тридцати.\n(открывает нижний ящик) Копии всех купюр. Я не верил ни им, ни вам.", "e4e94374-000e-52e3-bb26-9bec42b1c55b": "Данияр смотрит на страницу блокнота. На лице что-то вроде облегчения.\n— Почерк Валентины Петровны. «Шестьдесят» — это тысяч. «Семнадцать тридцать, Ташкентская».\nВы уже всё поняли. (снимает очки)\nДа. С пятницы знал. В милицию не пошёл — она просила.\nСорок тысяч взял из «чёрной» кассы. Вернул туда то, что выводил.\nЭтот номер на АОН, в пятнадцать тридцать... я своими глазами видел. Я там был, когда звонили.\nВ семнадцать тридцать оставил пакет на остановке. Темно. Высокий, молодой. Спортивная куртка, ушанка. Лица — нет.\nПотом база. С семнадцати пятидесяти пяти до девятнадцати десяти, журнал КПП подтвердит.\nС половины восьмого до половины второго — опять у неё.\n(выдвигает ящик) Копии купюр. Все. Возьмите.", "4cc34317-760f-577c-b05f-e0374aee4f23": "Данияр долго смотрит на строчку в журнале.\n— Двадцать восьмое октября. Шестнадцать десять. Да.\nЯ был в кабинете. Фархад пришёл просить свою долю. Спокойно. Вежливо. В галстуке пришёл.\nВы знаете, что он сидел? В девяносто четвёртом. За товар их с Игорем фирмы — взял на себя. Полтора года.\nИгорь ему тогда обещал всё сохранить.\nА тут при мне: «Я тебя садиться не просил. Хочешь — иди завскладом».\nФархад ничего не ответил. Встал и ушёл. Молча.\n(пауза) Я тогда подумал: лучше бы кричал.", "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba": "Данияр впервые повышает голос. И тут же снимает очки.\n— Помирились? Он так сказал?\nИгорь его выгнал. При мне. Двадцать восьмого октября, в кабинете.\nФархад пришёл свою долю просить. Вежливо. В галстуке.\nОн же в девяносто четвёртом сел за товар их с Игорем кооператива. Всё на себя взял. Полтора года.\nА Игорь ему: «Я тебя садиться не просил. Хочешь — иди завскладом».\nФархад ушёл. Молча.\n(кладёт очки дужками вверх) Если это «помирились»... я не знаю тогда, что такое ссора.", "0a295d5f-e115-5c89-a26a-5992761304a0": "— Виктор, значит.\n(поправляет очки)\nБыл разговор. По деньгам. Партнёры иногда ругаются.\nК тому, что с Игорем случилось, это отношения не имеет.", "9281d556-d163-5537-a0e2-e4cd2e635ba5": "— Значит, проверили. Хорошо.\n(выдыхает)\nЯ вам с самого начала говорил: я его не трогал. Деньги — да. Но не это.", "06da149b-c92c-54fa-a5f5-b78ff87dbc92": "— Вот видите. Сходится.\n(поправляет ручку на столе)\nЯ виноват перед Игорем. Но не в этом.", "5cdb3307-fe10-53c5-a365-6998256b7d7a": "— Фархад принёс. В воскресенье вечером, я там был. Он её по руке гладил. Пятьсот долларов у человека, который всем должен. Я тогда ещё подумал: откуда."}'::jsonb where id = 'a7955352-673d-5ff7-bfcc-506079544d1f';  -- Данияр Ахметов
update characters set reaction_rules = '[{"id": "R21", "on": "c50332f2-fb14-5cff-9ea2-9581024ac2e3", "requires": [], "text": "Ерлан читает листок. Пепел с сигареты падает на колено.\n— Да чё ты... Ладно. Ладно, братан.\nФархад. В девяносто третьем мать на операцию легла. Надо было полторы тысячи долларов. Он дал. Без расписки.\nЯ не вернул. Меня из органов попёрли — какие деньги.\nА за две недели до всего — в субботу, девятого — в чайхане у Зелёного он мне говорит: забудь долг. Только скажи, когда Игорь один ездит. Поговорить, мол, по-мужски. Без водилы.\nНу я и сказал: по четвергам.\nВ четверг он мне на пейджер: «в силе?». Я перезвонил. В силе.\nВсё. Думал — разговор.\nВ субботу находился на посту, с двадцати до восьми, отзвоны на пульт каждый час.\n(трёт колено) А когда Игоря нашли... гнал от себя. Молчал.", "grants": ["b229ab87-5e5b-5f61-8a7b-18c17718e4cf"]}, {"id": "R22", "on": "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "requires": [], "text": "Ерлан слушает выдержку из показаний. Тушит сигарету о край стола, мимо пепельницы.\n— Сдал, значит, Фархад-ака. Ну да.\nБыло. В девяносто третьем он мне полторы тысячи дал. На операцию матери. Я не вернул.\nА девятого, в субботу, в чайхане у Зелёного — недели за две до всего — говорит: спишу. Только скажи, когда Игорь без водилы ездит. Поговорить надо. По-мужски.\nЯ сказал: по четвергам.\nВ четверг на пейджер пришло: «в силе?». Я перезвонил, подтвердил.\nБольше ничего не знал, хоть режь. Думал — разговор.\nВ субботу на смене был. С двадцати до восьми, отзвоны на пульт каждый час. Проверяй.", "grants": ["b229ab87-5e5b-5f61-8a7b-18c17718e4cf"]}, {"id": "R121", "on": "06da149b-c92c-54fa-a5f5-b78ff87dbc92", "requires": [], "text": "Ерлан читает. Пепел с сигареты падает на колено. Не стряхивает.\n— «Наводчику». — Хмыкает. Нехорошо. — Слово-то какое. Протокольное.\n(пауза)\n— Ну сказал я ему про четверги. Сказал. В протоколе всё есть. А про подвал, про выкуп — не знал я, братан. Хоть режь.", "grants": [], "fallback": true}, {"id": "R248", "on": "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "requires": ["b229ab87-5e5b-5f61-8a7b-18c17718e4cf"], "text": "— Сдал, значит, Фархад-ака. Ну да. Я всё сказал, в протоколе есть. Больше ничего не знал, хоть режь.", "grants": [], "supersedes": ["R22"]}]'::jsonb, reactions = '{"c50332f2-fb14-5cff-9ea2-9581024ac2e3": "Ерлан читает листок. Пепел с сигареты падает на колено.\n— Да чё ты... Ладно. Ладно, братан.\nФархад. В девяносто третьем мать на операцию легла. Надо было полторы тысячи долларов. Он дал. Без расписки.\nЯ не вернул. Меня из органов попёрли — какие деньги.\nА за две недели до всего — в субботу, девятого — в чайхане у Зелёного он мне говорит: забудь долг. Только скажи, когда Игорь один ездит. Поговорить, мол, по-мужски. Без водилы.\nНу я и сказал: по четвергам.\nВ четверг он мне на пейджер: «в силе?». Я перезвонил. В силе.\nВсё. Думал — разговор.\nВ субботу находился на посту, с двадцати до восьми, отзвоны на пульт каждый час.\n(трёт колено) А когда Игоря нашли... гнал от себя. Молчал.", "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db": "Ерлан слушает выдержку из показаний. Тушит сигарету о край стола, мимо пепельницы.\n— Сдал, значит, Фархад-ака. Ну да.\nБыло. В девяносто третьем он мне полторы тысячи дал. На операцию матери. Я не вернул.\nА девятого, в субботу, в чайхане у Зелёного — недели за две до всего — говорит: спишу. Только скажи, когда Игорь без водилы ездит. Поговорить надо. По-мужски.\nЯ сказал: по четвергам.\nВ четверг на пейджер пришло: «в силе?». Я перезвонил, подтвердил.\nБольше ничего не знал, хоть режь. Думал — разговор.\nВ субботу на смене был. С двадцати до восьми, отзвоны на пульт каждый час. Проверяй."}'::jsonb where id = '2d9e7245-2e05-5079-86f1-f9b2edb1f3e9';  -- Ерлан Нуртазин
update characters set reaction_rules = '[{"id": "R18", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": [], "text": "Тамара Фёдоровна у забора. Пальто поверх халата. Смотрит, как Сеитова поднимается из люка с пакетом.\n— Gott… Значит, был там кто-то. Был. — Прижимает руку к груди. — Я всё скажу. У меня давление, я не сплю, у окна сижу. Дом Фархад продаёт. Покупателей водил, я его в лицо знаю. В среду сказал: скоро люди въедут.\nВ пятницу смотрю — дым. Из трубы. Под навесом машина тёмная, не наша, иномарка. Парень печку топил. Высокий, молодой.\nА в субботу в четверть седьмого — «Волга» белая. Одна фара. Вышли двое: Фархад, прямо в свет, и тот парень. Парень скоро пешком ушёл. И всё. Никаких покупателей, никто больше не приезжал.\nПотом свет отключили. Везде темно, а у Шмидтов керосинка. До ночи. — Пауза. — В двадцать минут двенадцатого иномарка со двора выехала. Без фар. Я её по мотору узнала, у наших так не урчит. А «Волга» у калитки до половины второго стояла. По свежему снегу уехала.", "grants": ["f725c4c5-f254-5c01-b718-3531a957102a"]}, {"id": "R19", "on": "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba", "requires": [], "text": "Тамара Фёдоровна держит справку на вытянутой руке. Очки в другой комнате.\n— Шмидты… Хорошие люди. Весной уехали, к сыну. Мои тоже там. А я вот жду. Бумаги жду. — Пауза. — Дом Фархад продаёт. По доверенности. Покупателей водил, я его в лицо знаю. В среду говорит: скоро въедут люди. Ну, я и думала — въехали.\nВ пятницу из трубы дым. Под навесом машина тёмная. Не наша, иномарка. Печку парень топил. Высокий. Молодой.\nА в субботу… по радио как раз новости кончились. Четверть седьмого. «Волга» белая, одна фара горит. Вышли Фархад и тот парень. Парень скоро ушёл. Пешком. А покупателей не было. Ну, ja, кто ж в темноте дом смотрит?\nПотом свет отключили. У меня давление, я не сплю. На всей улице одно окно светилось. У Шмидтов. Керосинка.\nВ двадцать минут двенадцатого иномарка выехала. Без фар. Я по мотору узнала. А «Волга» стояла. До половины второго. Уехала уже по снегу, по свежему. — Gott… Я же думала — покупатели.", "grants": ["f725c4c5-f254-5c01-b718-3531a957102a"]}, {"id": "R70", "on": "552b22f9-f4c6-5469-8d1c-56bde54906aa", "requires": [], "text": "Тамара Фёдоровна смотрит на аппарат.\n— Телефон? Не отключали, нет. Фархад сказал: покупатели звонить будут, пусть работает. Он и платил, наверное.\n(пауза)\nА кому оттуда звонить? Там же никого нет. Не было.", "grants": []}, {"id": "R86", "on": "2d1a03f4-be7f-5007-8fe1-71c12d498c29", "requires": [], "text": "— Доверенность? Да, Шмидты ему оставили, когда уезжали. Дом продавать.\nКлючи тоже у него. Он и покупателей водил.\n(качает головой)\nА доллары... Ну, ja. Это уж я не знаю.", "grants": []}, {"id": "R124", "on": "7188cb7d-2261-5a9c-8f78-e603caa6b31a", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "— Покупателю? — Тамара Фёдоровна даже привстаёт. — Gott… Какой покупатель? Никакого покупателя не было!\n(поправляет платок)\n— Я у окна сидела. С керосинкой. Двое вышли, он и парень. Парень ушёл пешком. И всё. Больше никто не приезжал, ни одна машина. Я бы слышала, деточка, у нас тут машин нету.\n— Вы ему так и скажите. Что Тамара не спала.", "grants": [], "fallback": true}, {"id": "R125", "on": "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "— При свечке? Дома? — Тамара Фёдоровна качает головой. — Ну, ja. Свечка, может, и была. Только не у него дома.\n(пауза)\n— «Волга» его у калитки стояла. До ночи. Я ещё думала: что ж он машину на улице бросил, разуют.\n— Я старая, но я не слепая. Так и запишите.", "grants": [], "fallback": true}, {"id": "R212", "on": "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "requires": [], "text": "— Свечка? В «Орбите»? Не знаю, деточка. Я про «Орбиту» ничего не знаю. Я своё видела, у Шмидтов.", "grants": [], "fallback": true}]'::jsonb, reactions = '{"c2c5ba62-e24e-523f-93bc-d8909b28e717": "Тамара Фёдоровна у забора. Пальто поверх халата. Смотрит, как Сеитова поднимается из люка с пакетом.\n— Gott… Значит, был там кто-то. Был. — Прижимает руку к груди. — Я всё скажу. У меня давление, я не сплю, у окна сижу. Дом Фархад продаёт. Покупателей водил, я его в лицо знаю. В среду сказал: скоро люди въедут.\nВ пятницу смотрю — дым. Из трубы. Под навесом машина тёмная, не наша, иномарка. Парень печку топил. Высокий, молодой.\nА в субботу в четверть седьмого — «Волга» белая. Одна фара. Вышли двое: Фархад, прямо в свет, и тот парень. Парень скоро пешком ушёл. И всё. Никаких покупателей, никто больше не приезжал.\nПотом свет отключили. Везде темно, а у Шмидтов керосинка. До ночи. — Пауза. — В двадцать минут двенадцатого иномарка со двора выехала. Без фар. Я её по мотору узнала, у наших так не урчит. А «Волга» у калитки до половины второго стояла. По свежему снегу уехала.", "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba": "Тамара Фёдоровна держит справку на вытянутой руке. Очки в другой комнате.\n— Шмидты… Хорошие люди. Весной уехали, к сыну. Мои тоже там. А я вот жду. Бумаги жду. — Пауза. — Дом Фархад продаёт. По доверенности. Покупателей водил, я его в лицо знаю. В среду говорит: скоро въедут люди. Ну, я и думала — въехали.\nВ пятницу из трубы дым. Под навесом машина тёмная. Не наша, иномарка. Печку парень топил. Высокий. Молодой.\nА в субботу… по радио как раз новости кончились. Четверть седьмого. «Волга» белая, одна фара горит. Вышли Фархад и тот парень. Парень скоро ушёл. Пешком. А покупателей не было. Ну, ja, кто ж в темноте дом смотрит?\nПотом свет отключили. У меня давление, я не сплю. На всей улице одно окно светилось. У Шмидтов. Керосинка.\nВ двадцать минут двенадцатого иномарка выехала. Без фар. Я по мотору узнала. А «Волга» стояла. До половины второго. Уехала уже по снегу, по свежему. — Gott… Я же думала — покупатели.", "552b22f9-f4c6-5469-8d1c-56bde54906aa": "Тамара Фёдоровна смотрит на аппарат.\n— Телефон? Не отключали, нет. Фархад сказал: покупатели звонить будут, пусть работает. Он и платил, наверное.\n(пауза)\nА кому оттуда звонить? Там же никого нет. Не было.", "2d1a03f4-be7f-5007-8fe1-71c12d498c29": "— Доверенность? Да, Шмидты ему оставили, когда уезжали. Дом продавать.\nКлючи тоже у него. Он и покупателей водил.\n(качает головой)\nА доллары... Ну, ja. Это уж я не знаю."}'::jsonb where id = '631694f6-0ec1-523d-9f2a-599f875223c1';  -- Тамара Фёдоровна Шнайдер
update characters set reaction_rules = '[{"id": "R25", "on": "d91852b9-daca-5340-80c9-a13cffe680cc", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "Олжас на краешке стула, руки зажаты между колен.\nНа столе — протокол сравнения купюр и показания соседки Шмидтов.\nОн смотрит в пол. Долго. Потом — быстро, не останавливаясь:\n— Ойбай... Ладно. Я.\nЯ его взял. У ворот, в четверг. Темно уже было.\nМашину его к Шмидтам перегнал, под навес. Водить умею. Прав нет.\nВ подвале у немцев держал. Кормил. Чай носил. Не бил, клянусь.\nМатери его из автоматов звонил. А в субботу на остановке автомат сломан — я из того дома позвонил.\nПакет на остановке я забрал. Деньги оттуда, да.\n(поднимает голову) Но аке ни при чём! Слышите? Я сам придумал. Сам.\nУтром его отпустили... ну, отпустил кто-то. Машина там же стояла, под навесом. Сел, поехал к себе на дачу. И угорел.\nБог наказал. Я его не трогал.", "grants": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"]}, {"id": "R26", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d", "107fcb2c-e909-5f81-bba4-d218265227c5"], "text": "Кабинет. На столе вспоротый мешок с рисом, протокол обыска. Олжас и Фархад друг напротив друга. Понятой смотрит в стену.\nВы зачитываете заключение Кана: задушен в субботу около десяти вечера, в машину посажен мёртвым. И говорите, где лежали остальные деньги.\nОлжас поворачивается к дяде.\n— Аке... Ты же сказал — утром отпустишь. За городом.\n(голос садится)\nТы меня за остановкой подобрал. Мы вдвоём приехали. Там, кроме нас, только он был.\nЯ тебе в четверть седьмого всё передал. Как он просил. «Фархад, я тебя узнал. Бери деньги и отпусти, никому не скажу».\nОн тебя через мешок узнал, аке. По кашлю. И «Беломором» от тебя пахло. Когда ты ему воду спускал.\nТы молчал. Три тысячи мне отсчитал.\nБез четверти семь: иди в общагу. Я пошёл.\n(закрывает лицо руками) Это я тебе сказал. Если б я не сказал...", "grants": ["3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c"]}, {"id": "R41", "on": "ed68230f-dcda-56e7-a77c-ecd7a4cc05a4", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d", "7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3"], "text": "Кабинет. Перед Олжасом журнал вахтёрши и заключение Кана: царапины на кисти дяди. Задушен в субботу около десяти вечера.\n— Ну да. В общаге был. С полвосьмого.\n(смотрит на строчку, потом на бумагу Кана)\nЗначит... Я в общаге. А с ним аке остался. Один.\nМы ж вдвоём туда приехали. Никого больше не было.\nИ Игорь его ногтями... в десять вечера...\n(пауза)\nЯ ему в четверть седьмого передал. Слова Игоря. «Фархад, я тебя узнал. Бери деньги и отпусти, никому не скажу».\nОн тебя через мешок узнал, аке. По кашлю. И «Беломором» пахло, когда воду спускал.\nАке ничего не сказал. Деньги забрал, мне три тысячи отсчитал.\nБез четверти семь отправил: иди, утром за городом его отпущу.\nОйбай... Он же сказал — никто не пострадает.", "grants": ["3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c"]}, {"id": "R42", "on": "87af9a91-8540-5177-bdd6-3e156802fc75", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a", "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e"], "text": "Перед Олжасом серый шарф из подвала. Вы пересказываете, что видели Данияр на остановке и соседка у дома Шмидтов: высокий, молодой, спортивная куртка, ушанка. Печь топил.\nОлжас смотрит на шарф. Глаз не отводит.\n— Он мёрз там...\n(и сразу, быстро)\nЯ его взял. В четверг, у ворот. Темно было.\nМашину к Шмидтам перегнал. Водить умею, прав нет.\nВ подвале держал. Матери его из автоматов звонил. А в субботу — из того дома, там телефон.\nПакет на остановке я забрал.\nНо аке ни при чём! Я сам придумал, слышите? Сам.\nУтром его отпустили, машину отдали — там же стояла, под навесом. Он на дачу поехал. И угорел. Бог наказал. Не я.\nСосед по комнате перестаёт притворяться спящим. На запястьях Олжаса щёлкают наручники.", "grants": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"]}, {"id": "R81", "on": "46e78eb0-d057-5e5d-8a00-81457f8f3d20", "requires": [], "text": "— Моё это. Куртка, шапка, ботинки.\nДеньги? Заработал. На базаре грузил, ночами.\n(смотрит в сторону)\nЧто, нельзя?", "grants": []}, {"id": "R82", "on": "9281d556-d163-5537-a0e2-e4cd2e635ba5", "requires": [], "text": "— Я же сказал уже. Держал его. Пальцы мои. А дальше меня там не было.", "grants": []}, {"id": "R90", "on": "abc6fac8-abbd-5589-b6b5-958cd368e7fe", "requires": [], "text": "— Аке руку поранил? Не знаю. Я его давно не видел. Работа, базар.\n(трёт ладони о колени)", "grants": []}, {"id": "R102", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": [], "text": "Олжас читает. Медленно, по слогам.\n— Задушен… — Поднимает глаза и сразу опускает. — Мен не знаю. Сартаков какой-то. Я не знаю его.\n(трёт ладони о колени. Больше не говорит)", "grants": [], "fallback": true}, {"id": "R103", "on": "27ae146a-a05c-5e7a-84a1-899c35e883e4", "requires": [], "text": "— Мамаджанов… — Олжас сжимает колени руками. — Аке дом продаёт. Он там везде трогал. Двери, лампы. Он работает там.\n(быстро)\n— Аке ни при чём. Слышите? Ни при чём.\n(про второй набор не спрашивает. Смотрит в пол)", "grants": [], "fallback": true}, {"id": "R104", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": [], "text": "Олжас слушает. На словах «высокий молодой парень» перестаёт дышать.\n— Высоких много. Мен не знаю.\n(пауза)\n— Аке туда покупателей возит. Он дом продаёт, он там всегда. Бабка старая, ей видится.\n(тихо, в пол)\n— Аке ни при чём. Ни при чём.", "grants": [], "fallback": true}, {"id": "R105", "on": "6fc41a46-a0eb-5890-9b26-3b19bcef490d", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "— У гаража? Аке? — Олжас мотает головой. — Ночью?\n(быстро, сбивчиво)\n— Нет. Он же сам поехал. Игорь. Машина его под навесом стояла, утром отпустили — сел, поехал. Сам.\n— Аке там не было. Он мне сказал: утром отпущу. Он не врёт мне. Не врёт.", "grants": [], "fallback": true}, {"id": "R106", "on": "107fcb2c-e909-5f81-bba4-d218265227c5", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "— В рисе?.. — Олжас поднимает голову. — Это я. Я ему отдал. На хранение.\n(торопится)\n— Он не знал, откуда. Я сказал — заработал. Он поверил. Он мне всегда верит.\n(пауза)\n— Аке ни при чём. Я сам.", "grants": [], "fallback": true}, {"id": "R107", "on": "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "Олжас читает. Потом ещё раз, с начала.\n— Сам. Один. — Плечи начинают дрожать. — Он сказал: никто не пострадает… Ойбай… Апа узнает…", "grants": [], "fallback": true}, {"id": "R108", "on": "6a92b637-cb0c-5bf4-8495-f503839bf08c", "requires": [], "text": "— Ну племянник. Апа моя ему сестра двоюродная. Это нельзя, что ли?\n(смотрит в пол)\n— Четыреста двенадцать. Тут все знают.\n— Аке мне помогает. Он родной. А что?", "grants": [], "fallback": true}, {"id": "R191", "on": "46e78eb0-d057-5e5d-8a00-81457f8f3d20", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "— Моё. Куртка, шапка, ботинки. — Смотрит в пол. — Деньги аке дал. Три тысячи. Я сказал уже.", "grants": [], "supersedes": ["R81"]}, {"id": "R192", "on": "27ae146a-a05c-5e7a-84a1-899c35e883e4", "requires": ["3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c"], "text": "— Его пальцы. Он там был. Со мной и после меня. — Смотрит в пол. — Я уже всё сказал.", "grants": [], "supersedes": ["R103"], "fallback": true}, {"id": "R193", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "— Это я был. Высокий. — Пауза. — Я пешком ушёл. А аке остался. Она правду говорит.", "grants": [], "supersedes": ["R104"], "fallback": true}, {"id": "R194", "on": "6fc41a46-a0eb-5890-9b26-3b19bcef490d", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d", "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c"], "text": "— У гаража… — Долго молчит. — Значит, он его туда и отвёз. Ночью. А мне сказал: утром за городом отпущу.", "grants": [], "supersedes": ["R105"], "fallback": true}, {"id": "R195", "on": "107fcb2c-e909-5f81-bba4-d218265227c5", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d", "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c"], "text": "— В рисе… Это всё, что от тех денег. Я ему пакет отдал, он мне три тысячи отсчитал. Остальное его.", "grants": [], "supersedes": ["R106"], "fallback": true}, {"id": "R197", "on": "abc6fac8-abbd-5589-b6b5-958cd368e7fe", "requires": ["3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c"], "text": "— Это Игорь его. Ногтями.\n(закрывает лицо руками)\n— А я в общаге был.", "grants": [], "supersedes": ["R90"]}, {"id": "R213", "on": "87af9a91-8540-5177-bdd6-3e156802fc75", "requires": ["ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "f725c4c5-f254-5c01-b718-3531a957102a", "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c"], "text": "Олжас берёт шарф. Долго держит.\n— Он мёрз там. Я ему этот шарф под голову положил. — Пауза. — Я всё сказал уже. И про аке сказал.", "grants": [], "supersedes": ["R42"]}, {"id": "R214", "on": "d91852b9-daca-5340-80c9-a13cffe680cc", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a", "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c"], "text": "— Деньги оттуда. Три тысячи аке отсчитал, в доме у немцев. — Смотрит в пол. — Я всё сказал уже.", "grants": [], "supersedes": ["R25"]}, {"id": "R229", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d", "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c", "107fcb2c-e909-5f81-bba4-d218265227c5"], "text": "Олжас читает. Поднимает глаза.\n— Около десяти… Я в общаге был. А он с ним остался. — Закрывает лицо руками. — Я всё сказал на очной ставке.", "grants": [], "supersedes": ["R26"]}, {"id": "R230", "on": "ed68230f-dcda-56e7-a77c-ecd7a4cc05a4", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d", "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c", "7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3"], "text": "— Ну да. С полвосьмого в общаге. — Смотрит в пол. — А он там один остался. Я сказал уже.", "grants": [], "supersedes": ["R41"]}, {"id": "R231", "on": "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba", "requires": [], "text": "Олжас смотрит на фамилию. Пальцы сжимают колени.\n— Шмидт… Мен не знаю. Немцы какие-то. — Быстро: — Аке там дом продаёт. Я там не был.", "grants": [], "fallback": true}]'::jsonb, reactions = '{"d91852b9-daca-5340-80c9-a13cffe680cc": "Олжас на краешке стула, руки зажаты между колен.\nНа столе — протокол сравнения купюр и показания соседки Шмидтов.\nОн смотрит в пол. Долго. Потом — быстро, не останавливаясь:\n— Ойбай... Ладно. Я.\nЯ его взял. У ворот, в четверг. Темно уже было.\nМашину его к Шмидтам перегнал, под навес. Водить умею. Прав нет.\nВ подвале у немцев держал. Кормил. Чай носил. Не бил, клянусь.\nМатери его из автоматов звонил. А в субботу на остановке автомат сломан — я из того дома позвонил.\nПакет на остановке я забрал. Деньги оттуда, да.\n(поднимает голову) Но аке ни при чём! Слышите? Я сам придумал. Сам.\nУтром его отпустили... ну, отпустил кто-то. Машина там же стояла, под навесом. Сел, поехал к себе на дачу. И угорел.\nБог наказал. Я его не трогал.", "54bf13bc-3525-5eec-9441-609d8ee21f59": "Кабинет. На столе вспоротый мешок с рисом, протокол обыска. Олжас и Фархад друг напротив друга. Понятой смотрит в стену.\nВы зачитываете заключение Кана: задушен в субботу около десяти вечера, в машину посажен мёртвым. И говорите, где лежали остальные деньги.\nОлжас поворачивается к дяде.\n— Аке... Ты же сказал — утром отпустишь. За городом.\n(голос садится)\nТы меня за остановкой подобрал. Мы вдвоём приехали. Там, кроме нас, только он был.\nЯ тебе в четверть седьмого всё передал. Как он просил. «Фархад, я тебя узнал. Бери деньги и отпусти, никому не скажу».\nОн тебя через мешок узнал, аке. По кашлю. И «Беломором» от тебя пахло. Когда ты ему воду спускал.\nТы молчал. Три тысячи мне отсчитал.\nБез четверти семь: иди в общагу. Я пошёл.\n(закрывает лицо руками) Это я тебе сказал. Если б я не сказал...", "ed68230f-dcda-56e7-a77c-ecd7a4cc05a4": "Кабинет. Перед Олжасом журнал вахтёрши и заключение Кана: царапины на кисти дяди. Задушен в субботу около десяти вечера.\n— Ну да. В общаге был. С полвосьмого.\n(смотрит на строчку, потом на бумагу Кана)\nЗначит... Я в общаге. А с ним аке остался. Один.\nМы ж вдвоём туда приехали. Никого больше не было.\nИ Игорь его ногтями... в десять вечера...\n(пауза)\nЯ ему в четверть седьмого передал. Слова Игоря. «Фархад, я тебя узнал. Бери деньги и отпусти, никому не скажу».\nОн тебя через мешок узнал, аке. По кашлю. И «Беломором» пахло, когда воду спускал.\nАке ничего не сказал. Деньги забрал, мне три тысячи отсчитал.\nБез четверти семь отправил: иди, утром за городом его отпущу.\nОйбай... Он же сказал — никто не пострадает.", "87af9a91-8540-5177-bdd6-3e156802fc75": "Перед Олжасом серый шарф из подвала. Вы пересказываете, что видели Данияр на остановке и соседка у дома Шмидтов: высокий, молодой, спортивная куртка, ушанка. Печь топил.\nОлжас смотрит на шарф. Глаз не отводит.\n— Он мёрз там...\n(и сразу, быстро)\nЯ его взял. В четверг, у ворот. Темно было.\nМашину к Шмидтам перегнал. Водить умею, прав нет.\nВ подвале держал. Матери его из автоматов звонил. А в субботу — из того дома, там телефон.\nПакет на остановке я забрал.\nНо аке ни при чём! Я сам придумал, слышите? Сам.\nУтром его отпустили, машину отдали — там же стояла, под навесом. Он на дачу поехал. И угорел. Бог наказал. Не я.\nСосед по комнате перестаёт притворяться спящим. На запястьях Олжаса щёлкают наручники.", "46e78eb0-d057-5e5d-8a00-81457f8f3d20": "— Моё это. Куртка, шапка, ботинки.\nДеньги? Заработал. На базаре грузил, ночами.\n(смотрит в сторону)\nЧто, нельзя?", "9281d556-d163-5537-a0e2-e4cd2e635ba5": "— Я же сказал уже. Держал его. Пальцы мои. А дальше меня там не было.", "abc6fac8-abbd-5589-b6b5-958cd368e7fe": "— Аке руку поранил? Не знаю. Я его давно не видел. Работа, базар.\n(трёт ладони о колени)"}'::jsonb where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c';  -- Олжас Бекенов
update characters set reaction_rules = '[{"id": "R208", "on": "6a92b637-cb0c-5bf4-8495-f503839bf08c", "requires": [], "text": "— Четыреста двенадцатая. Бекенов, есть такой. Грузчик, с базара. Тихий. Журнал у меня, смотрите.", "grants": [], "fallback": true}]'::jsonb, reactions = '{}'::jsonb where id = 'ad04679a-62fd-52ac-a043-6e04873ad6b3';  -- Роза-апа Сагинтаева
commit;
select sum(jsonb_array_length(reaction_rules)) rules from characters where case_id = '029e23c3-01e0-5d19-a0e7-3e0c2446ebab';
